const searchData = {"envversion": {"sphinx.domains.c": 3, "sphinx.domains.changeset": 1, "sphinx.domains.citation": 1, "sphinx.domains.cpp": 9, "sphinx.domains.index": 1, "sphinx.domains.javascript": 3, "sphinx.domains.math": 2, "sphinx.domains.python": 4, "sphinx.domains.rst": 2, "sphinx.domains.std": 2, "sphinx.ext.intersphinx": 1, "repo_docs.ext.toctree": 2, "repo_docs.ext.enhanced_search": 2, "sphinx": 62}, "data": [{"id": 0, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#api-types", "display_name": "API Types", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "api-types", "priority": -1, "content": "Both services provide dual APIs:  gRPC API : Protocol Buffer-based, high-performance, strongly-typed  REST API : HTTP/JSON-based, easier for testing and web clients Use gRPC for production microservices and REST for web clients or when easier HTTP tooling is preferred.", "keywords": []}, {"id": 1, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#authentication", "display_name": "Authentication", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "authentication", "priority": -1, "content": "Include a bearer token in all requests:  gRPC : metadata = [(&#x27;authorization&#x27;, &#x27;Bearer YOUR_TOKEN&#x27;)]  REST : Authorization: Bearer YOUR_TOKEN", "keywords": []}, {"id": 2, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#base-urls", "display_name": "Base URLs", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "base-urls", "priority": -1, "content": "gRPC : your-aggregation-service.example.com:50051  REST : https://your-aggregation-service.example.com", "keywords": []}, {"id": 3, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#batchpublishevents", "display_name": "BatchPublishEvents", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "batchpublishevents", "priority": -1, "content": "Publishes multiple events in parallel.  Request : BatchPublishEventsRequest message BatchPublishEventsRequest { repeated Event events = 1; }  Response : BatchPublishEventsResponse message BatchPublishEventsResponse { repeated PublishingResult results = 1; }  Note : Each event in the batch has its own result. Some may succeed while others fail.  Example : # Create multiple events events = [event1, event2, event3] # Batch publish request = event_publisher_pb2.BatchPublishEventsRequest() for event in events: request.events.append(event) response = stub.BatchPublishEvents(request, metadata=metadata) # Check individual results for idx, result in enumerate(response.results): if result.success: print(f&quot;Event {idx} published&quot;) else: print(f&quot;Event {idx} failed: {result.failure_reason}&quot;)", "keywords": []}, {"id": 4, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#common-grpc-status-codes", "display_name": "Common gRPC Status Codes", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "common-grpc-status-codes", "priority": -1, "content": "Code Meaning Action OK Success Process response INVALID_ARGUMENT Bad request Check request format UNAUTHENTICATED Auth failed Refresh token PERMISSION_DENIED No permission Check permissions NOT_FOUND Resource not found Check identifiers RESOURCE_EXHAUSTED Service overloaded Retry with backoff INTERNAL Server error Retry after delay", "keywords": []}, {"id": 5, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#common-http-status-codes", "display_name": "Common HTTP Status Codes", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "common-http-status-codes", "priority": -1, "content": "Code Meaning Action 200 Success Process response 400 Bad Request Check request format 401 Unauthorized Refresh authentication token 403 Forbidden Check permissions 404 Not Found Check queue_id or endpoint 422 Validation Error Check request validation 500 Internal Server Error Retry after delay, contact support 503 Service Unavailable Retry with exponential backoff", "keywords": []}, {"id": 6, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#consumedurableevents", "display_name": "ConsumeDurableEvents", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "consumedurableevents", "priority": -1, "content": "Streams events from a durable queue (server streaming).  Request : ConsumeDurableEventsRequest message ConsumeDurableEventsRequest { string queue_id = 1; }  Response : ConsumeDurableEventsResponse (stream) message ConsumeDurableEventsResponse { repeated Event events = 1; }  Example : request = event_consumer_pb2.ConsumeDurableEventsRequest( queue_id=&#x27;saved-queue-id&#x27; ) responses = stub.ConsumeDurableEvents(request, metadata=metadata) for response in responses: for event in response.events: process_event(event)", "keywords": []}, {"id": 7, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#consumenondurableevents", "display_name": "ConsumeNonDurableEvents", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "consumenondurableevents", "priority": -1, "content": "Streams events using a non-durable queue (bidirectional streaming).  Request : ConsumeNonDurableEventsRequest (stream) message ConsumeNonDurableEventsRequest { repeated FilterGroup filter_groups = 1; optional string reconnect_token = 2; } message FilterGroup { string event_type = 1; repeated ResourceFilter filters = 2; } message ResourceFilter { enum FilterType { FILTER_TYPE_UNSPECIFIED = 0; FILTER_TYPE_EQ = 1; FILTER_TYPE_STARTS_WITH_LAZY = 2; FILTER_TYPE_STARTS_WITH_GREEDY = 3; } FilterType filter_type = 1; string resource_id = 2; }  Response : ConsumeNonDurableEventsResponse (stream) message ConsumeNonDurableEventsResponse { repeated Event events = 1; string reconnect_token = 2; } message Event { string event_type = 1; string principal_identity = 2; google.protobuf.Timestamp occurred_at = 3; google.protobuf.Timestamp published_at = 4; google.protobuf.Struct message = 5; }  Example : # Create filter filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;myapp.user.created&#x27; ) # No filters added - receive all events of this type # Request stream def request_stream(): request = event_consumer_pb2.ConsumeNonDurableEventsRequest() request.filter_groups.append(filter_group) yield request # Consume responses = stub.ConsumeNonDurableEvents(request_stream(), metadata=metadata) for response in responses: reconnect_token = response.reconnect_token # Save for reconnection for event in response.events: print(f&quot;Event: {event.event_type}&quot;) print(f&quot;Message: {event.message}&quot;)", "keywords": []}, {"id": 8, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#createdurablequeue", "display_name": "CreateDurableQueue", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "createdurablequeue", "priority": -1, "content": "Creates a durable queue for persistent event storage.  Request : CreateDurableQueueRequest message CreateDurableQueueRequest { repeated FilterGroup filter_groups = 1; }  Response : CreateDurableQueueResponse message CreateDurableQueueResponse { string queue_id = 1; // Save this! }  Example : filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;myapp.file.uploaded&#x27; ) resource_filter = event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/uploads/&#x27; ) filter_group.filters.append(resource_filter) request = event_consumer_pb2.CreateDurableQueueRequest() request.filter_groups.append(filter_group) response = stub.CreateDurableQueue(request, metadata=metadata) queue_id = response.queue_id # IMPORTANT: Save queue_id to configuration", "keywords": []}, {"id": 9, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#delete-api-v1beta-queues-durable", "display_name": "DELETE /api/v1beta/queues/durable", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "delete-api-v1beta-queues-durable", "priority": -1, "content": "Deletes a durable queue.  Query Parameters : Parameter Type Required Description queue_id string Yes ID of the queue to delete  Response (200 OK): { &quot;success&quot;: true }  Example : curl -X DELETE &quot;https://your-consumer-service.example.com/api/v1beta/queues/durable?queue_id=my-queue-id&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot;", "keywords": []}, {"id": 10, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#deletedurablequeue", "display_name": "DeleteDurableQueue", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "deletedurablequeue", "priority": -1, "content": "Deletes a durable queue.  Request : DeleteDurableQueueRequest message DeleteDurableQueueRequest { string queue_id = 1; }  Response : DeleteDurableQueueResponse message DeleteDurableQueueResponse {}  Example : request = event_consumer_pb2.DeleteDurableQueueRequest( queue_id=queue_id ) stub.DeleteDurableQueue(request, metadata=metadata)", "keywords": []}, {"id": 11, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#event-aggregation-service-publisher-api", "display_name": "Event Aggregation Service (Publisher API)", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "event-aggregation-service-publisher-api", "priority": -1, "content": "The Event Aggregation Service accepts events from publishers and routes them to consumers.", "keywords": []}, {"id": 12, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#event-consumer-service-consumer-api", "display_name": "Event Consumer Service (Consumer API)", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "event-consumer-service-consumer-api", "priority": -1, "content": "The Event Consumer Service allows clients to stream events with filtering.", "keywords": []}, {"id": 13, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#get-api-v1beta-events-stream", "display_name": "GET /api/v1beta/events/stream", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "get-api-v1beta-events-stream", "priority": -1, "content": "Streams events using a non-durable queue (Server-Sent Events).  Query Parameters : Parameter Type Required Description filter_groups string (JSON) No URL-encoded JSON array of FilterGroup objects reconnect_token string No Token for reconnecting to same queue  FilterGroup Structure : [ { &quot;event_type&quot;: &quot;string&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/path/&quot; } ] } ]  Filter Types : EQ : Exact match STARTS_WITH_LAZY : Shallow prefix match STARTS_WITH_GREEDY : Deep prefix match UNSPECIFIED : Defaults to EQ  Response (text/event-stream): event: message id: 12345 data: {&quot;event_type&quot;:&quot;myapp.user.created&quot;,&quot;principal_identity&quot;:&quot;user@example.com&quot;,&quot;occurred_at&quot;:&quot;2024-10-16T14:30:00Z&quot;,&quot;published_at&quot;:&quot;2024-10-16T14:30:01Z&quot;,&quot;message&quot;:{&quot;user_id&quot;:&quot;123&quot;}} event: reconnect_token data: {&quot;reconnect_token&quot;:&quot;abc123xyz&quot;}  Example : # Simple consumption curl -N https://your-consumer-service.example.com/api/v1beta/events/stream \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; # With filtering FILTERS=&#x27;[{&quot;event_type&quot;:&quot;myapp.user.created&quot;,&quot;filters&quot;:[]}]&#x27; curl -N https://your-consumer-service.example.com/api/v1beta/events/stream \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -G --data-urlencode &quot;filter_groups=$FILTERS&quot;", "keywords": []}, {"id": 14, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#get-api-v1beta-events-stream-durable", "display_name": "GET /api/v1beta/events/stream-durable", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "get-api-v1beta-events-stream-durable", "priority": -1, "content": "Streams events from a durable queue (Server-Sent Events).  Query Parameters : Parameter Type Required Description queue_id string Yes ID of the durable queue  Response (text/event-stream): event: message id: 12345 data: {&quot;event_type&quot;:&quot;myapp.user.created&quot;,...} event: message id: 12346 data: {&quot;event_type&quot;:&quot;myapp.user.updated&quot;,...}  Example : curl -N https://your-consumer-service.example.com/api/v1beta/events/stream-durable?queue_id=my-queue-id \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot;", "keywords": []}, {"id": 15, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#id1", "display_name": "Base URLs", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "id1", "priority": -1, "content": "gRPC : your-consumer-service.example.com:50052  REST : https://your-consumer-service.example.com", "keywords": []}, {"id": 16, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#id2", "display_name": "Service Definition", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "id2", "priority": -1, "content": "service EventConsumerService { rpc ConsumeNonDurableEvents(stream ConsumeNonDurableEventsRequest) returns (stream ConsumeNonDurableEventsResponse); rpc ConsumeDurableEvents(ConsumeDurableEventsRequest) returns (stream ConsumeDurableEventsResponse); rpc CreateDurableQueue(CreateDurableQueueRequest) returns (CreateDurableQueueResponse); rpc UpdateDurableQueue(UpdateDurableQueueRequest) returns (UpdateDurableQueueResponse); rpc DeleteDurableQueue(DeleteDurableQueueRequest) returns (DeleteDurableQueueResponse); }", "keywords": []}, {"id": 17, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#metrics-and-monitoring", "display_name": "Metrics and Monitoring", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "metrics-and-monitoring", "priority": -1, "content": "Both services expose OpenTelemetry metrics and traces when telemetry is enabled via configuration.", "keywords": []}, {"id": 18, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#next-steps", "display_name": "Next Steps", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "next-steps", "priority": -1, "content": "Try the Getting Started Guide for hands-on examples Learn about Publishing Events Learn about Consuming Events Understand Permissions &amp; Authorization", "keywords": []}, {"id": 19, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#openapi-specifications", "display_name": "OpenAPI Specifications", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "openapi-specifications", "priority": -1, "content": "Full OpenAPI specifications are available in the released archive", "keywords": []}, {"id": 20, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#patch-api-v1beta-queues-durable", "display_name": "PATCH /api/v1beta/queues/durable", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "patch-api-v1beta-queues-durable", "priority": -1, "content": "Updates filters on a durable queue.  Request Body : { &quot;queue_id&quot;: &quot;string&quot;, &quot;current_filter_groups&quot;: [ /* array of FilterGroup */ ], &quot;new_filter_groups&quot;: [ /* array of FilterGroup */ ] }  Response (200 OK): { &quot;success&quot;: true }", "keywords": []}, {"id": 21, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#post-api-v1beta-events", "display_name": "POST /api/v1beta/events", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "post-api-v1beta-events", "priority": -1, "content": "Publishes a single event.  Request Body : { &quot;event&quot;: { &quot;event_type&quot;: &quot;string&quot;, &quot;message&quot;: {}, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/path/to/resource&quot; } } }  Response (200 OK): { &quot;result&quot;: { &quot;event&quot;: { /* echo of event */ }, &quot;success&quot;: true } }  Response (200 OK, but publish failed): { &quot;result&quot;: { &quot;event&quot;: { /* echo of event */ }, &quot;success&quot;: false, &quot;failure_reason&quot;: &quot;Unable to connect to message broker&quot; } }  Error Responses : Status Code Description 400 Invalid request format 401 Unauthenticated 403 Permission denied 422 Validation error 503 Service unavailable - retry  Example : curl -X POST https://your-aggregation-service.example.com/api/v1beta/events \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;event&quot;: { &quot;event_type&quot;: &quot;myapp.user.created&quot;, &quot;message&quot;: { &quot;user_id&quot;: &quot;123&quot;, &quot;username&quot;: &quot;john_doe&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/users/123&quot; } } }&#x27;", "keywords": []}, {"id": 22, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#post-api-v1beta-events-batch", "display_name": "POST /api/v1beta/events/batch", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "post-api-v1beta-events-batch", "priority": -1, "content": "Publishes multiple events in parallel.  Request Body : { &quot;events&quot;: [ { &quot;event_type&quot;: &quot;string&quot;, &quot;message&quot;: {}, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/path/to/resource&quot; } } ] }  Response (200 OK): { &quot;results&quot;: [ { &quot;event&quot;: { /* event 1 */ }, &quot;success&quot;: true }, { &quot;event&quot;: { /* event 2 */ }, &quot;success&quot;: false, &quot;failure_reason&quot;: &quot;Publish failed&quot; } ] }  Example : curl -X POST https://your-aggregation-service.example.com/api/v1beta/events/batch \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;events&quot;: [ { &quot;event_type&quot;: &quot;myapp.file.uploaded&quot;, &quot;message&quot;: {&quot;file&quot;: &quot;doc1.pdf&quot;}, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot; }, { &quot;event_type&quot;: &quot;myapp.file.uploaded&quot;, &quot;message&quot;: {&quot;file&quot;: &quot;doc2.pdf&quot;}, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:01Z&quot; } ] }&#x27;", "keywords": []}, {"id": 23, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#post-api-v1beta-queues-durable", "display_name": "POST /api/v1beta/queues/durable", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "post-api-v1beta-queues-durable", "priority": -1, "content": "Creates a durable queue.  Request Body : { &quot;filter_groups&quot;: [ { &quot;event_type&quot;: &quot;string&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/path/&quot; } ] } ] }  Response (200 OK): { &quot;queue_id&quot;: &quot;durable-queue-abc123&quot; }  Example : curl -X POST https://your-consumer-service.example.com/api/v1beta/queues/durable \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;filter_groups&quot;: [ { &quot;event_type&quot;: &quot;myapp.file.uploaded&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] } ] }&#x27;", "keywords": []}, {"id": 24, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#protocol-buffer-files", "display_name": "Protocol Buffer Files", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "protocol-buffer-files", "priority": -1, "content": "The complete protocol buffer definitions are available in the released archive or protobuf registry.  Publisher Proto : nvidia/omniverse/notifications/publisher/v1beta/event_publisher.proto  Consumer Proto : nvidia/omniverse/notifications/consumer/v1beta/event_consumer.proto", "keywords": []}, {"id": 25, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#publishevent", "display_name": "PublishEvent", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "publishevent", "priority": -1, "content": "Publishes a single event.  Request : PublishEventRequest message PublishEventRequest { Event event = 1; } message Event { string event_type = 1; google.protobuf.Struct message = 2; google.protobuf.Timestamp occurred_at = 3; EventResource resource = 4; // Optional } message EventResource { string resource_id = 1; }  Response : PublishEventResponse message PublishEventResponse { PublishingResult result = 1; } message PublishingResult { Event event = 1; bool success = 2; string failure_reason = 3; // Only set if success is false }  Errors : gRPC Status Code Meaning UNAUTHENTICATED Invalid or expired authentication token PERMISSION_DENIED Not authorized to publish this event type INVALID_ARGUMENT Invalid event structure RESOURCE_EXHAUSTED Service temporarily overloaded - retry with backoff INTERNAL Server error  Example : from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2 # Create event event = event_publisher_pb2.Event( event_type=&#x27;myapp.user.created&#x27;, message=message_struct, occurred_at=timestamp, resource=event_publisher_pb2.EventResource( resource_id=&#x27;/users/123&#x27; ) ) # Publish request = event_publisher_pb2.PublishEventRequest(event=event) response = stub.PublishEvent(request, metadata=metadata) if response.result.success: print(&quot;Published successfully&quot;)", "keywords": []}, {"id": 26, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#rate-limits-and-quotas", "display_name": "Rate Limits and Quotas", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "rate-limits-and-quotas", "priority": -1, "content": "Currently, there are no enforced rate limits at the application level. However: The service may return RESOURCE_EXHAUSTED (gRPC) or 503 (HTTP) if temporarily overloaded Implement exponential backoff when you receive these errors For high-volume publishing, use batch publishing for better performance", "keywords": []}, {"id": 27, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#service-definition", "display_name": "Service Definition", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "service-definition", "priority": -1, "content": "service EventPublishingService { rpc PublishEvent(PublishEventRequest) returns (PublishEventResponse); rpc BatchPublishEvents(BatchPublishEventsRequest) returns (BatchPublishEventsResponse); }", "keywords": []}, {"id": 28, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#service-health", "display_name": "Service Health", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "service-health", "priority": -1, "content": "Both services expose health check endpoints:  gRPC : Standard gRPC health checking protocol  REST : GET /health - Service health status Returns 200 if healthy", "keywords": []}, {"id": 29, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#updatedurablequeue", "display_name": "UpdateDurableQueue", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "updatedurablequeue", "priority": -1, "content": "Updates filters on an existing durable queue.  Request : UpdateDurableQueueRequest message UpdateDurableQueueRequest { string queue_id = 1; repeated FilterGroup current_filter_groups = 2; repeated FilterGroup new_filter_groups = 3; }  Response : UpdateDurableQueueResponse message UpdateDurableQueueResponse {}", "keywords": []}, {"id": 30, "doc_id": 31, "filename": "api-reference.html", "domain_name": "page", "name": "api-reference#versioning", "display_name": "Versioning", "type": "section", "display_type": "Page section", "docname": "api-reference", "anchor": "versioning", "priority": -1, "content": "The current API version is v1beta . APIs are under the /api/v1beta/ path (REST) or v1beta package (gRPC) Beta APIs may change, but we will maintain backward compatibility where possible When the API reaches GA, it will be versioned as v1", "keywords": []}, {"id": 31, "doc_id": 31, "filename": "api-reference.html", "domain_name": "std", "name": "api-reference", "display_name": "API Reference", "type": "doc", "display_type": "Page", "docname": "api-reference", "anchor": "", "priority": -1, "content": "This page provides detailed reference information for both the Event Aggregation Service (Publisher API) and Event Consumer Service (Consumer API).", "keywords": []}, {"id": 32, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#authorization-errors-during-streaming", "display_name": "Authorization Errors During Streaming", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "authorization-errors-during-streaming", "priority": -1, "content": "Important : Authorization errors can occur at any time during streaming, not just at connection time. For example: Your authentication token expires while streaming Permissions change while you\u2019re connected When this happens, the stream will terminate with a 401 (UNAUTHENTICATED) or 403 (PERMISSION_DENIED) error.  Handling in REST/SSE : import time def consume_with_auto_reconnect(url, get_token_func, queue_id=None): &quot;&quot;&quot; Consume events with automatic reconnection on auth errors. &quot;&quot;&quot; while True: try: token = get_token_func() # Get fresh token headers = { &quot;Authorization&quot;: f&quot;Bearer {token}&quot;, &quot;Accept&quot;: &quot;text/event-stream&quot; } params = {} if queue_id: params[&quot;queue_id&quot;] = queue_id response = requests.get(url, headers=headers, params=params, stream=True) if response.status_code == 401 or response.status_code == 403: print(&quot;Auth error, refreshing token...&quot;) time.sleep(1) continue client = sseclient.SSEClient(response) for event in client.events(): if event.event == &quot;message&quot;: process_event(json.loads(event.data)) except requests.exceptions.RequestException as e: print(f&quot;Connection error: {e}, reconnecting...&quot;) time.sleep(5)  Handling in gRPC : def consume_with_retry(stub, queue_id, get_token_func): &quot;&quot;&quot; Consume with automatic reconnection on auth errors. &quot;&quot;&quot; while True: try: token = get_token_func() metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {token}&#x27;)] request = event_consumer_pb2.ConsumeDurableEventsRequest( queue_id=queue_id ) responses = stub.ConsumeDurableEvents(request, metadata=metadata) for response in responses: for event in response.events: process_event(event) except grpc.RpcError as e: if e.code() in [grpc.StatusCode.UNAUTHENTICATED, grpc.StatusCode.PERMISSION_DENIED]: print(&quot;Auth error, refreshing token and reconnecting...&quot;) time.sleep(1) elif e.code() == grpc.StatusCode.RESOURCE_EXHAUSTED: print(&quot;Service overloaded, backing off...&quot;) time.sleep(5) else: print(f&quot;Error: {e.code()}: {e.details()}&quot;) time.sleep(5)", "keywords": []}, {"id": 33, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#choose-the-right-queue-type", "display_name": "1. Choose the Right Queue Type", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "choose-the-right-queue-type", "priority": -1, "content": "See the decision matrix above.", "keywords": []}, {"id": 34, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#complete-example-thumbnail-generation-service", "display_name": "Complete Example: Thumbnail Generation Service", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "complete-example-thumbnail-generation-service", "priority": -1, "content": "Here\u2019s a complete example of a service that generates thumbnails for uploaded images using a durable queue: import grpc import logging from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2 from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2_grpc logging.basicConfig(level=logging.INFO) logger = logging.getLogger(__name__) class ThumbnailService: def __init__(self, consumer_endpoint, auth_token): self.consumer_endpoint = consumer_endpoint self.auth_token = auth_token self.queue_id = None def setup(self): &quot;&quot;&quot;Create durable queue - call once during deployment.&quot;&quot;&quot; channel = grpc.secure_channel( self.consumer_endpoint, grpc.ssl_channel_credentials() ) stub = event_consumer_pb2_grpc.EventConsumerServiceStub(channel) # Create queue for image upload events filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;storage.file.created&#x27; ) resource_filter = event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/images/&#x27; ) filter_group.filters.append(resource_filter) request = event_consumer_pb2.CreateDurableQueueRequest() request.filter_groups.append(filter_group) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {self.auth_token}&#x27;)] response = stub.CreateDurableQueue(request, metadata=metadata) self.queue_id = response.queue_id logger.info(f&quot;Created durable queue: {self.queue_id}&quot;) # SAVE THIS QUEUE_ID TO YOUR CONFIG! def run(self, queue_id): &quot;&quot;&quot;Run the service - consumes events and generates thumbnails.&quot;&quot;&quot; self.queue_id = queue_id while True: try: channel = grpc.secure_channel( self.consumer_endpoint, grpc.ssl_channel_credentials() ) stub = event_consumer_pb2_grpc.EventConsumerServiceStub(channel) request = event_consumer_pb2.ConsumeDurableEventsRequest( queue_id=self.queue_id ) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {self.auth_token}&#x27;)] logger.info(&quot;Starting to consume events...&quot;) responses = stub.ConsumeDurableEvents(request, metadata=metadata) for response in responses: for event in response.events: self.process_event(event) except grpc.RpcError as e: logger.error(f&quot;gRPC error: {e.code()}: {e.details()}&quot;) if e.code() in [grpc.StatusCode.UNAUTHENTICATED, grpc.StatusCode.PERMISSION_DENIED]: # Refresh token and reconnect self.auth_token = self.get_fresh_token() logger.info(&quot;Refreshed auth token, reconnecting...&quot;) else: logger.error(&quot;Connection failed, retrying in 5s...&quot;) time.sleep(5) def process_event(self, event): &quot;&quot;&quot;Process a single file created event.&quot;&quot;&quot; try: file_path = event.message.get(&#x27;file_path&#x27;, &#x27;&#x27;) logger.info(f&quot;Processing file: {file_path}&quot;) # Generate thumbnail self.generate_thumbnail(file_path) logger.info(f&quot;Thumbnail generated for: {file_path}&quot;) except Exception as e: logger.error(f&quot;Error processing event: {e}&quot;) # Don&#x27;t raise - continue processing other events def generate_thumbnail(self, file_path): &quot;&quot;&quot;Generate thumbnail for the given file.&quot;&quot;&quot; # Implementation here pass def get_fresh_token(self): &quot;&quot;&quot;Get a fresh auth token.&quot;&quot;&quot; # Implementation here pass # Usage if __name__ == &quot;__main__&quot;: service = ThumbnailService( consumer_endpoint=&quot;your-consumer-service.example.com:50052&quot;, auth_token=&quot;YOUR_TOKEN&quot; ) # One-time setup (or load from config) # service.setup() # Run service with saved queue_id service.run(queue_id=&quot;saved-queue-id-from-config&quot;)", "keywords": []}, {"id": 35, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#consuming-with-durable-queues", "display_name": "Consuming with Durable Queues", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "consuming-with-durable-queues", "priority": -1, "content": "Durable queues require a three-step process: create, consume, delete.", "keywords": []}, {"id": 36, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#decision-matrix", "display_name": "Decision Matrix", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "decision-matrix", "priority": -1, "content": "Scenario Recommended Choice Reason UI real-time notifications  Non-durable  Users only care about what\u2019s happening now File processing pipeline  Durable  Must process every file Live dashboard  Non-durable  Current state is what matters Email notification service  Durable  Must send every notification Development/testing  Non-durable  Easier, no cleanup needed Production microservice  Durable  Can\u2019t miss events during restarts Webhook relay  Durable  Must deliver all webhooks Activity feed  Non-durable  Only recent activity matters", "keywords": []}, {"id": 37, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#delete-durable-queues-when-done", "display_name": "6. Delete Durable Queues When Done", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "delete-durable-queues-when-done", "priority": -1, "content": "Always delete durable queues when your application is decommissioned: # In your application shutdown handler def cleanup(): stub.DeleteDurableQueue( DeleteDurableQueueRequest(queue_id=queue_id), metadata=metadata )", "keywords": []}, {"id": 38, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#don-t-block-the-event-stream", "display_name": "4. Don\u2019t Block the Event Stream", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "don-t-block-the-event-stream", "priority": -1, "content": "Process events quickly or hand them off to a worker: import threading import queue event_queue = queue.Queue() def event_processor(): &quot;&quot;&quot;Worker thread to process events.&quot;&quot;&quot; while True: event = event_queue.get() if event is None: break process_event_slowly(event) # Start worker worker = threading.Thread(target=event_processor) worker.start() # Consume events quickly for response in responses: for event in response.events: event_queue.put(event) # Don&#x27;t block the stream", "keywords": []}, {"id": 39, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#durable-queues", "display_name": "Durable Queues", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "durable-queues", "priority": -1, "content": "What they are:  Persistent queues that must be explicitly created before use Store events even when you\u2019re disconnected Receive all events from the time the queue was created  Must be explicitly deleted when no longer needed  When to use:  Critical event processing where no events can be missed Microservices that need to process every event Batch processing workflows Systems that may have downtime for deployments Event-driven architectures where events trigger actions  Advantages:   No events are lost - all events since queue creation are preserved Can disconnect and reconnect without losing messages Events are queued up during downtime Reliable for building event-driven systems  Disadvantages:  Requires explicit queue lifecycle management (create/delete) Consumes storage resources Need to persist the queue_id in your application configuration Must remember to delete queues when done  Example use cases:  \u2713 Thumbnail generation service processing every file upload \u2713 Notification delivery service sending emails for events \u2713 Data synchronization between services \u2713 Audit logging where every event must be recorded \u2717 UI notifications (non-durable is simpler) \u2717 Temporary development testing (non-durable is easier)", "keywords": []}, {"id": 40, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#durable-vs-non-durable-queues", "display_name": "Durable vs Non-Durable Queues", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "durable-vs-non-durable-queues", "priority": -1, "content": "One of the most important decisions when consuming events is whether to use a durable queue or a non-durable queue . Understanding the difference is critical for building reliable applications.", "keywords": []}, {"id": 41, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#empty-resource-id", "display_name": "Empty Resource ID", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "empty-resource-id", "priority": -1, "content": "Special behavior for resource_id=&quot;&quot; : # STARTS_WITH_GREEDY with empty resource_id: receive ALL events of this type { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;&quot; } # STARTS_WITH_LAZY with empty resource_id: receive events with no resource # or single-level resources { &quot;filter_type&quot;: &quot;starts_with_lazy&quot;, &quot;resource_id&quot;: &quot;&quot; } # EQ with empty resource_id: ERROR (not allowed) { &quot;filter_type&quot;: &quot;eq&quot;, &quot;resource_id&quot;: &quot;&quot; }", "keywords": []}, {"id": 42, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#eq-exact-match", "display_name": "1. EQ (Exact Match)", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "eq-exact-match", "priority": -1, "content": "Matches only exact resource_id: { &quot;filter_type&quot;: &quot;eq&quot;, &quot;resource_id&quot;: &quot;/projects/project1/file.txt&quot; } # Matches: /projects/project1/file.txt # No match: /projects/project1/file2.txt # No match: /projects/project1/sub/file.txt", "keywords": []}, {"id": 43, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#filter-types", "display_name": "Filter Types", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "filter-types", "priority": -1, "content": "Three types of resource filters are available:", "keywords": []}, {"id": 44, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#grpc-api", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "grpc-api", "priority": -1, "content": "RPC : ConsumeNonDurableEvents (bidirectional streaming)  Python Example : import grpc from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2 from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2_grpc # Setup channel and stub channel = grpc.secure_channel( &#x27;your-consumer-service.example.com:50052&#x27;, grpc.ssl_channel_credentials() ) stub = event_consumer_pb2_grpc.EventConsumerServiceStub(channel) # Define filters filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;storage.file.created&#x27; ) resource_filter = event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/uploads/&#x27; ) filter_group.filters.append(resource_filter) # Create request stream def request_stream(): # Send initial request with filters request = event_consumer_pb2.ConsumeNonDurableEventsRequest() request.filter_groups.append(filter_group) yield request # Keep stream open (or send updated filters later) # Start consuming metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] responses = stub.ConsumeNonDurableEvents(request_stream(), metadata=metadata) reconnect_token = None try: for response in responses: # Save reconnect token for potential reconnection if response.reconnect_token: reconnect_token = response.reconnect_token # Process events for event in response.events: print(f&quot;Event type: {event.event_type}&quot;) print(f&quot;Occurred at: {event.occurred_at}&quot;) print(f&quot;Message: {event.message}&quot;) print(f&quot;Published by: {event.principal_identity}&quot;) print(&quot;---&quot;) except grpc.RpcError as e: if e.code() == grpc.StatusCode.UNAUTHENTICATED: print(&quot;Token expired - reconnect with new token&quot;) # Reconnect with new token and reconnect_token  Reconnecting with Token : def request_stream_reconnect(reconnect_token): request = event_consumer_pb2.ConsumeNonDurableEventsRequest( reconnect_token=reconnect_token ) yield request # Reconnect to same queue responses = stub.ConsumeNonDurableEvents( request_stream_reconnect(reconnect_token), metadata=new_metadata )  Updating Filters Dynamically : The bidirectional stream allows you to update filters while consuming. When sending an update request, you must include both the new filters in filter_groups and the previous filters in previous_filter_groups : import threading import queue # Track current filters so we can send them as previous_filter_groups current_filters = [] def request_stream_dynamic(filter_queue, initial_filters): global current_filters # Send initial filters initial_request = event_consumer_pb2.ConsumeNonDurableEventsRequest() for fg in initial_filters: initial_request.filter_groups.append(fg) current_filters = initial_filters yield initial_request # Wait for filter updates while True: new_filters = filter_queue.get() # Blocks until new filters available if new_filters is None: # Sentinel to stop break # Create update request with both new and previous filters update_request = event_consumer_pb2.ConsumeNonDurableEventsRequest() for fg in new_filters: update_request.filter_groups.append(fg) for fg in current_filters: update_request.previous_filter_groups.append(fg) # Update our tracking of current filters current_filters = new_filters yield update_request # Initial filters initial_filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;storage.file.created&#x27; ) resource_filter = event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/uploads/&#x27; ) initial_filter_group.filters.append(resource_filter) initial_filters = [initial_filter_group] filter_queue = queue.Queue() responses = stub.ConsumeNonDurableEvents( request_stream_dynamic(filter_queue, initial_filters), metadata=metadata ) # Later, update filters to add a new event type new_filter_group_1 = event_consumer_pb2.FilterGroup( event_type=&#x27;storage.file.created&#x27; ) new_filter_group_1.filters.append(event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/uploads/&#x27; )) new_filter_group_2 = event_consumer_pb2.FilterGroup( event_type=&#x27;storage.file.deleted&#x27; ) new_filter_group_2.filters.append(event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/uploads/&#x27; )) # Send updated filters - the request_stream_dynamic function will # automatically include the previous filters filter_queue.put([new_filter_group_1, new_filter_group_2])  Important Notes on Updating Filters (gRPC) : When updating filters, you must provide both filter_groups (new filters) and previous_filter_groups (old filters) If filter_groups equals previous_filter_groups , no update is performed The server uses previous_filter_groups to determine which bindings to remove when updating the queue", "keywords": []}, {"id": 45, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#handle-disconnections-gracefully", "display_name": "2. Handle Disconnections Gracefully", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "handle-disconnections-gracefully", "priority": -1, "content": "# Non-durable: Save reconnect_token reconnect_token = None for response in responses: if response.reconnect_token: reconnect_token = response.reconnect_token # Use it to reconnect request = ConsumeNonDurableEventsRequest(reconnect_token=reconnect_token) # Durable: Just use the same queue_id request = ConsumeDurableEventsRequest(queue_id=saved_queue_id)", "keywords": []}, {"id": 46, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id1", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id1", "priority": -1, "content": "Endpoint : POST /api/v1beta/queues/durable curl -X POST &quot;https://your-consumer-service.example.com/api/v1beta/queues/durable&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;filter_groups&quot;: [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] } ] }&#x27;  Response : { &quot;queue_id&quot;: &quot;durable-queue-abc123xyz&quot; }  Important : Save the queue_id - you\u2019ll need it for consuming and deleting!", "keywords": []}, {"id": 47, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id2", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id2", "priority": -1, "content": "RPC : CreateDurableQueue import grpc from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2 from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2_grpc # Setup channel and stub channel = grpc.secure_channel( &#x27;your-consumer-service.example.com:50052&#x27;, grpc.ssl_channel_credentials() ) stub = event_consumer_pb2_grpc.EventConsumerServiceStub(channel) # Define filters filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;storage.file.created&#x27; ) resource_filter = event_consumer_pb2.ResourceFilter( filter_type=event_consumer_pb2.ResourceFilter.FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&#x27;/uploads/&#x27; ) filter_group.filters.append(resource_filter) # Create durable queue request = event_consumer_pb2.CreateDurableQueueRequest() request.filter_groups.append(filter_group) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] response = stub.CreateDurableQueue(request, metadata=metadata) queue_id = response.queue_id print(f&quot;Created durable queue: {queue_id}&quot;) # IMPORTANT: Save this queue_id to your application config!", "keywords": []}, {"id": 48, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id3", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id3", "priority": -1, "content": "Endpoint : GET /api/v1beta/events/stream-durable curl -N GET &quot;https://your-consumer-service.example.com/api/v1beta/events/stream-durable?queue_id=durable-queue-abc123xyz&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot;  Python Example : import sseclient import requests import json url = &quot;https://your-consumer-service.example.com/api/v1beta/events/stream-durable&quot; headers = { &quot;Authorization&quot;: f&quot;Bearer {YOUR_TOKEN}&quot;, &quot;Accept&quot;: &quot;text/event-stream&quot; } params = {&quot;queue_id&quot;: queue_id} response = requests.get(url, headers=headers, params=params, stream=True) client = sseclient.SSEClient(response) for event in client.events(): if event.event == &quot;message&quot;: data = json.loads(event.data) process_event(data)  Reconnecting : Just use the same queue_id - no reconnect token needed: # After disconnection or application restart response = requests.get(url, headers=headers, params=params, stream=True) # Will continue from where you left off", "keywords": []}, {"id": 49, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id4", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id4", "priority": -1, "content": "RPC : ConsumeDurableEvents import grpc from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2 from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2_grpc # Setup channel and stub channel = grpc.secure_channel( &#x27;your-consumer-service.example.com:50052&#x27;, grpc.ssl_channel_credentials() ) stub = event_consumer_pb2_grpc.EventConsumerServiceStub(channel) # Consume from durable queue request = event_consumer_pb2.ConsumeDurableEventsRequest( queue_id=queue_id # Use the saved queue_id ) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] try: responses = stub.ConsumeDurableEvents(request, metadata=metadata) for response in responses: for event in response.events: print(f&quot;Event type: {event.event_type}&quot;) print(f&quot;Message: {event.message}&quot;) # Process event except grpc.RpcError as e: if e.code() == grpc.StatusCode.UNAUTHENTICATED: # Refresh token and reconnect with same queue_id print(&quot;Token expired, reconnecting...&quot;)", "keywords": []}, {"id": 50, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id5", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id5", "priority": -1, "content": "Endpoint : DELETE /api/v1beta/queues/durable curl -X DELETE &quot;https://your-consumer-service.example.com/api/v1beta/queues/durable?queue_id=durable-queue-abc123xyz&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot;  Response : { &quot;success&quot;: true }", "keywords": []}, {"id": 51, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id6", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id6", "priority": -1, "content": "RPC : DeleteDurableQueue request = event_consumer_pb2.DeleteDurableQueueRequest( queue_id=queue_id ) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] response = stub.DeleteDurableQueue(request, metadata=metadata) print(&quot;Queue deleted successfully&quot;)", "keywords": []}, {"id": 52, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id7", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id7", "priority": -1, "content": "Endpoint : PATCH /api/v1beta/queues/durable curl -X PATCH &quot;https://your-consumer-service.example.com/api/v1beta/queues/durable&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;queue_id&quot;: &quot;durable-queue-abc123xyz&quot;, &quot;current_filter_groups&quot;: [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [] } ], &quot;new_filter_groups&quot;: [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [] }, { &quot;event_type&quot;: &quot;storage.file.deleted&quot;, &quot;filters&quot;: [] } ] }&#x27;", "keywords": []}, {"id": 53, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#id8", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "id8", "priority": -1, "content": "RPC : UpdateDurableQueue request = event_consumer_pb2.UpdateDurableQueueRequest( queue_id=queue_id ) for fg in current_filters: request.current_filter_groups.append(fg) for fg in new_filters: request.new_filter_groups.append(fg) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] response = stub.UpdateDurableQueue(request, metadata=metadata)", "keywords": []}, {"id": 54, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#key-principle", "display_name": "Key Principle", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "key-principle", "priority": -1, "content": "If missing an event would break your application or cause data inconsistency, use a durable queue. If events are only relevant \u201cin the moment,\u201d use a non-durable queue.", "keywords": []}, {"id": 55, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#monitor-queue-depth-durable-queues", "display_name": "5. Monitor Queue Depth (Durable Queues)", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "monitor-queue-depth-durable-queues", "priority": -1, "content": "If you\u2019re not consuming fast enough, the durable queue will grow. Monitor this and scale your consumers if needed.", "keywords": []}, {"id": 56, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#multiple-event-types", "display_name": "Multiple Event Types", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "multiple-event-types", "priority": -1, "content": "Multiple FilterGroups let you subscribe to multiple event types: [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ {&quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot;} ] }, { &quot;event_type&quot;: &quot;storage.file.deleted&quot;, &quot;filters&quot;: [ {&quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot;} ] } ]", "keywords": []}, {"id": 57, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#multiple-filters-or-logic", "display_name": "Multiple Filters (OR Logic)", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "multiple-filters-or-logic", "priority": -1, "content": "Multiple filters within a FilterGroup use OR logic: # Receive events from /uploads/ OR /shared/ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; }, { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/shared/&quot; } ] }", "keywords": []}, {"id": 58, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#next-steps", "display_name": "Next Steps", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "next-steps", "priority": -1, "content": "Understand Permissions &amp; Authorization for consuming events Review the API Reference for complete API documentation Learn about Publishing Events", "keywords": []}, {"id": 59, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#non-durable-queues", "display_name": "Non-Durable Queues", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "non-durable-queues", "priority": -1, "content": "What they are:  Temporary queues created automatically when you start consuming Only receive events that occur while you are connected  Automatically deleted after disconnection (after a brief TTL) No setup required - just start streaming  When to use:  Real-time notifications in UI applications Live dashboards and monitoring displays Event logging where missing some events is acceptable Prototyping and development Scenarios where events are only relevant \u201cright now\u201d  Advantages:  Simple - no queue management needed Lightweight - no persistent storage Automatic cleanup Good for applications with many concurrent users (each gets their own temporary queue)  Disadvantages:   Events occurring while disconnected are lost  Not suitable for critical event processing  Example use cases:  \u2713 Showing &quot;Someone just uploaded a file&quot; notifications in a web UI \u2713 Live activity feed in a dashboard \u2713 Real-time log streaming during development \u2717 Processing every file upload for thumbnail generation (use durable) \u2717 Triggering critical workflows (use durable) \u2717 Syncing data between services (use durable)", "keywords": []}, {"id": 60, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#other-common-errors", "display_name": "Other Common Errors", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "other-common-errors", "priority": -1, "content": "HTTP Status / gRPC Code Meaning Action 400 / INVALID_ARGUMENT Invalid filter_groups or queue_id Check your request format 404 / NOT_FOUND Queue not found (durable) Verify queue_id is correct 503 / RESOURCE_EXHAUSTED Service temporarily overloaded Retry with exponential backoff", "keywords": []}, {"id": 61, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#overview", "display_name": "Overview", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "overview", "priority": -1, "content": "The Event Consumer Service allows clients to stream events in real-time. You can filter events by event type and resource ID, and choose between durable and non-durable consumption modes.", "keywords": []}, {"id": 62, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#process-events-idempotently", "display_name": "3. Process Events Idempotently", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "process-events-idempotently", "priority": -1, "content": "Events may be delivered more than once (rare but possible). Design your event handlers to be idempotent: def process_event(event): event_id = get_event_id(event) # Check if already processed if redis.exists(f&quot;processed:{event_id}&quot;): print(f&quot;Event {event_id} already processed, skipping&quot;) return # Process event do_work(event) # Mark as processed redis.set(f&quot;processed:{event_id}&quot;, &quot;1&quot;, ex=86400) # 24h TTL", "keywords": []}, {"id": 63, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#rest-api", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "rest-api", "priority": -1, "content": "Endpoint : GET /api/v1beta/events/stream The REST API uses Server-Sent Events (SSE) for streaming.  Basic Example (No Filtering) : # Consume all events of all types curl -N GET &quot;https://your-consumer-service.example.com/api/v1beta/events/stream&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot;  With Event Type Filtering : # Create filter groups as JSON FILTERS=&#x27;[ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [] } ]&#x27; # URL encode and pass as query parameter curl -N GET &quot;https://your-consumer-service.example.com/api/v1beta/events/stream&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -G --data-urlencode &quot;filter_groups=$FILTERS&quot;  With Resource Filtering : # Only receive events for files in /uploads/ directory and subdirectories FILTERS=&#x27;[ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] } ]&#x27; curl -N GET &quot;https://your-consumer-service.example.com/api/v1beta/events/stream&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -G --data-urlencode &quot;filter_groups=$FILTERS&quot;  Response Format : event: message id: 12345 data: {&quot;event_type&quot;:&quot;storage.file.created&quot;,&quot;principal_identity&quot;:&quot;user@example.com&quot;,&quot;occurred_at&quot;:&quot;2024-10-16T14:30:00Z&quot;,&quot;published_at&quot;:&quot;2024-10-16T14:30:01Z&quot;,&quot;message&quot;:{&quot;file_name&quot;:&quot;doc.pdf&quot;}} event: reconnect_token data: {&quot;reconnect_token&quot;:&quot;abc123xyz&quot;} event: message id: 12346 data: {&quot;event_type&quot;:&quot;storage.file.created&quot;,&quot;principal_identity&quot;:&quot;user2@example.com&quot;,&quot;occurred_at&quot;:&quot;2024-10-16T14:31:00Z&quot;,&quot;published_at&quot;:&quot;2024-10-16T14:31:01Z&quot;,&quot;message&quot;:{&quot;file_name&quot;:&quot;image.png&quot;}}  Python Example with SSE Client : import sseclient import requests import json url = &quot;https://your-consumer-service.example.com/api/v1beta/events/stream&quot; headers = { &quot;Authorization&quot;: f&quot;Bearer {YOUR_TOKEN}&quot;, &quot;Accept&quot;: &quot;text/event-stream&quot; } # Define filters filters = [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] } ] params = {&quot;filter_groups&quot;: json.dumps(filters)} # Stream events response = requests.get(url, headers=headers, params=params, stream=True) client = sseclient.SSEClient(response) for event in client.events(): if event.event == &quot;message&quot;: data = json.loads(event.data) print(f&quot;Received: {data[&#x27;event_type&#x27;]}&quot;) print(f&quot;Message: {data[&#x27;message&#x27;]}&quot;) elif event.event == &quot;reconnect_token&quot;: token_data = json.loads(event.data) reconnect_token = token_data[&#x27;reconnect_token&#x27;] print(f&quot;Reconnect token: {reconnect_token}&quot;)  Reconnecting After Disconnection : If your connection drops, use the reconnect_token to reconnect to the same queue and avoid missing events: curl -N GET &quot;https://your-consumer-service.example.com/api/v1beta/events/stream?reconnect_token=abc123xyz&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot;  Updating Filters Dynamically (REST) : You can update filters on a non-durable queue while it continues to exist. This is useful when you need to change what events you\u2019re listening for without losing the queue. To update filters, make a new request with the reconnect_token , the new filter_groups , and the previous_filter_groups : # Original filters we were using PREV_FILTERS=&#x27;[ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] } ]&#x27; # New filters we want to use NEW_FILTERS=&#x27;[ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] }, { &quot;event_type&quot;: &quot;storage.file.deleted&quot;, &quot;filters&quot;: [ { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot; } ] } ]&#x27; # Reconnect with updated filters curl -N GET &quot;https://your-consumer-service.example.com/api/v1beta/events/stream&quot; \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -G --data-urlencode &quot;reconnect_token=abc123xyz&quot; \\ --data-urlencode &quot;filter_groups=$NEW_FILTERS&quot; \\ --data-urlencode &quot;previous_filter_groups=$PREV_FILTERS&quot;  Python Example with Filter Updates : import sseclient import requests import json def consume_with_filter_updates(): url = &quot;https://your-consumer-service.example.com/api/v1beta/events/stream&quot; headers = { &quot;Authorization&quot;: f&quot;Bearer {YOUR_TOKEN}&quot;, &quot;Accept&quot;: &quot;text/event-stream&quot; } # Initial filters current_filters = [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ {&quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot;} ] } ] params = {&quot;filter_groups&quot;: json.dumps(current_filters)} reconnect_token = None # Start consuming response = requests.get(url, headers=headers, params=params, stream=True) client = sseclient.SSEClient(response) for event in client.events(): if event.event == &quot;reconnect_token&quot;: token_data = json.loads(event.data) reconnect_token = token_data[&#x27;reconnect_token&#x27;] elif event.event == &quot;message&quot;: data = json.loads(event.data) process_event(data) # Example: Update filters after some condition if should_update_filters(): # Close current connection response.close() # Define new filters new_filters = [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;filters&quot;: [ {&quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot;} ] }, { &quot;event_type&quot;: &quot;storage.file.deleted&quot;, &quot;filters&quot;: [ {&quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/uploads/&quot;} ] } ] # Reconnect with updated filters params = { &quot;reconnect_token&quot;: reconnect_token, &quot;filter_groups&quot;: json.dumps(new_filters), &quot;previous_filter_groups&quot;: json.dumps(current_filters) } response = requests.get(url, headers=headers, params=params, stream=True) client = sseclient.SSEClient(response) # Update our tracking of current filters current_filters = new_filters  Important Notes on Updating Filters (REST) : When updating filters, you must provide both filter_groups (new filters) and previous_filter_groups (old filters) The reconnect_token identifies which queue to update The queue must already exist (you cannot update filters before making an initial consume request) If filter_groups equals previous_filter_groups , no update is performed", "keywords": []}, {"id": 64, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#starts-with-greedy-deep-prefix-match", "display_name": "3. STARTS_WITH_GREEDY (Deep Prefix Match)", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "starts-with-greedy-deep-prefix-match", "priority": -1, "content": "Matches resources at any depth under the prefix: { &quot;filter_type&quot;: &quot;starts_with_greedy&quot;, &quot;resource_id&quot;: &quot;/projects/project1/&quot; } # Matches: /projects/project1/file.txt # Matches: /projects/project1/subfolder/file.txt # Matches: /projects/project1/a/b/c/d/file.txt # No match: /projects/project10/file.txt", "keywords": []}, {"id": 65, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#starts-with-lazy-shallow-prefix-match", "display_name": "2. STARTS_WITH_LAZY (Shallow Prefix Match)", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "starts-with-lazy-shallow-prefix-match", "priority": -1, "content": "Matches resources at the same level or one level deep: { &quot;filter_type&quot;: &quot;starts_with_lazy&quot;, &quot;resource_id&quot;: &quot;/projects/project1/&quot; } # Matches: /projects/project1/file.txt # No match: /projects/project1/subfolder/file.txt (too deep) # No match: /projects/project10/file.txt (not a prefix match)", "keywords": []}, {"id": 66, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#step-1-create-a-durable-queue", "display_name": "Step 1: Create a Durable Queue", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "step-1-create-a-durable-queue", "priority": -1, "content": "This is typically done once during application setup or deployment, not in your regular application code.", "keywords": []}, {"id": 67, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#step-2-consume-from-durable-queue", "display_name": "Step 2: Consume from Durable Queue", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "step-2-consume-from-durable-queue", "priority": -1, "content": "Now consume events using the queue_id. Your application can disconnect and reconnect using the same queue_id.", "keywords": []}, {"id": 68, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#step-3-delete-durable-queue", "display_name": "Step 3: Delete Durable Queue", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "step-3-delete-durable-queue", "priority": -1, "content": "When your application no longer needs the queue (e.g., during decommissioning), delete it to free resources.", "keywords": []}, {"id": 69, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#updating-durable-queue-filters", "display_name": "Updating Durable Queue Filters", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "updating-durable-queue-filters", "priority": -1, "content": "You can update filters on an existing durable queue without deleting it:", "keywords": []}, {"id": 70, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "page", "name": "consuming-events#use-appropriate-filters", "display_name": "7. Use Appropriate Filters", "type": "section", "display_type": "Page section", "docname": "consuming-events", "anchor": "use-appropriate-filters", "priority": -1, "content": "Don\u2019t receive more events than you need: # Bad - receiving all events then filtering in code bad_filter_group = FilterGroup(event_type=&quot;storage.file.created&quot;) # No filters - receiving everything for response in responses: for event in response.events: if event.message[&#x27;file_name&#x27;].endswith(&#x27;.pdf&#x27;): process(event) # Wasting bandwidth # Better - filter by resource if possible better_filter_group = FilterGroup( event_type=&quot;storage.file.created&quot; ) resource_filter = ResourceFilter( filter_type=FILTER_TYPE_STARTS_WITH_GREEDY, resource_id=&quot;/pdfs/&quot; # Only get events from /pdfs/ ) better_filter_group.filters.append(resource_filter)", "keywords": []}, {"id": 71, "doc_id": 71, "filename": "consuming-events.html", "domain_name": "std", "name": "consuming-events", "display_name": "Consuming Events", "type": "doc", "display_type": "Page", "docname": "consuming-events", "anchor": "", "priority": -1, "content": "This guide covers how to consume events from the Notifications Service using both the REST API and gRPC API, including detailed information about durable and non-durable queues.", "keywords": []}, {"id": 72, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#authentication", "display_name": "Authentication", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "authentication", "priority": -1, "content": "Both services require authentication. Include your bearer token in requests:  REST : Include the Authorization header: Authorization: Bearer YOUR_TOKEN_HERE  gRPC : Include the token in metadata: # Python example metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)]", "keywords": []}, {"id": 73, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#connection-drops", "display_name": "Connection drops", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "connection-drops", "priority": -1, "content": "For non-durable queues, use the reconnect_token to reconnect to the same queue. For durable queues, just reconnect with the same queue_id .", "keywords": []}, {"id": 74, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#define-your-event-types", "display_name": "1. Define Your Event Types", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "define-your-event-types", "priority": -1, "content": "Before implementing, define your event type naming convention: # Example event type definitions USER_CREATED = &quot;myapp.user.created&quot; USER_UPDATED = &quot;myapp.user.updated&quot; USER_DELETED = &quot;myapp.user.deleted&quot; FILE_UPLOADED = &quot;myapp.file.uploaded&quot; WORKFLOW_COMPLETED = &quot;myapp.workflow.completed&quot;", "keywords": []}, {"id": 75, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#define-your-message-schemas", "display_name": "2. Define Your Message Schemas", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "define-your-message-schemas", "priority": -1, "content": "Document the structure of messages for each event type: # Example: myapp.user.created message schema { &quot;user_id&quot;: str, # Required: Unique user identifier &quot;username&quot;: str, # Required: User&#x27;s username &quot;email&quot;: str, # Required: User&#x27;s email &quot;created_by&quot;: str, # Optional: Who created this user &quot;metadata&quot;: dict # Optional: Additional metadata }", "keywords": []}, {"id": 76, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#events-not-being-received", "display_name": "Events not being received", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "events-not-being-received", "priority": -1, "content": "Check that your filter groups match the event types being published Verify your authentication token is valid Ensure the publisher is successfully publishing events", "keywords": []}, {"id": 77, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#handle-errors", "display_name": "3. Handle Errors", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "handle-errors", "priority": -1, "content": "Both publishing and consuming can fail. Always handle errors appropriately: # Publishing with error handling try: response = stub.PublishEvent(request, metadata=metadata) if response.result.success: print(&quot;Event published successfully&quot;) else: print(f&quot;Failed to publish: {response.result.failure_reason}&quot;) except grpc.RpcError as e: if e.code() == grpc.StatusCode.RESOURCE_EXHAUSTED: # Retry with exponential backoff print(&quot;Service temporarily unavailable, retrying...&quot;) elif e.code() == grpc.StatusCode.PERMISSION_DENIED: print(&quot;Permission denied - check your authorization&quot;) else: print(f&quot;Unexpected error: {e.details()}&quot;)", "keywords": []}, {"id": 78, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#next-steps", "display_name": "Next Steps", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "next-steps", "priority": -1, "content": "Now that you\u2019ve published and consumed your first events: Learn more about Publishing Events including batch publishing Explore Consuming Events including durable queues and filtering Understand Permissions &amp; Authorization to secure your events Review the API Reference for complete API documentation", "keywords": []}, {"id": 79, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#permission-denied-errors", "display_name": "\u201cPermission denied\u201d errors", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "permission-denied-errors", "priority": -1, "content": "Make sure you have the appropriate permissions configured. See the Permissions guide.", "keywords": []}, {"id": 80, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#prerequisites", "display_name": "Prerequisites", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "prerequisites", "priority": -1, "content": "Access to a deployed Notifications Service (Event Aggregation and Event Consumer services) Authentication credentials (JWT token or similar) For gRPC: Protocol Buffer compiler and gRPC libraries for your language For REST: HTTP client library (or just curl for testing)", "keywords": []}, {"id": 81, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#quick-example-publish-and-consume-an-event", "display_name": "Quick Example: Publish and Consume an Event", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "quick-example-publish-and-consume-an-event", "priority": -1, "content": "Let\u2019s walk through a complete example of publishing an event and consuming it.", "keywords": []}, {"id": 82, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#service-unavailable-errors", "display_name": "\u201cService unavailable\u201d errors", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "service-unavailable-errors", "priority": -1, "content": "The service may be temporarily overloaded. Implement retry logic with exponential backoff.", "keywords": []}, {"id": 83, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#step-1-generate-client-code", "display_name": "Step 1: Generate Client Code", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "step-1-generate-client-code", "priority": -1, "content": "First, obtain the proto files from the released archive or protobuf registry. Generate client code for your language: # Python example python -m grpc_tools.protoc \\ -I./protos \\ --python_out=. \\ --grpc_python_out=. \\ nvidia/omniverse/notifications/publisher/v1beta/event_publisher.proto \\ nvidia/omniverse/notifications/consumer/v1beta/event_consumer.proto", "keywords": []}, {"id": 84, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#step-1-publish-an-event-rest", "display_name": "Step 1: Publish an Event (REST)", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "step-1-publish-an-event-rest", "priority": -1, "content": "curl -X POST https://your-aggregation-service.example.com/api/v1beta/events \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;event&quot;: { &quot;event_type&quot;: &quot;myapp.user.created&quot;, &quot;message&quot;: { &quot;user_id&quot;: &quot;12345&quot;, &quot;username&quot;: &quot;john_doe&quot;, &quot;email&quot;: &quot;john@example.com&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/users/12345&quot; } } }&#x27;  Response : { &quot;result&quot;: { &quot;event&quot;: { &quot;event_type&quot;: &quot;myapp.user.created&quot;, &quot;message&quot;: { &quot;user_id&quot;: &quot;12345&quot;, &quot;username&quot;: &quot;john_doe&quot;, &quot;email&quot;: &quot;john@example.com&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/users/12345&quot; } }, &quot;success&quot;: true } }", "keywords": []}, {"id": 85, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#step-2-consume-events-rest-with-sse", "display_name": "Step 2: Consume Events (REST with SSE)", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "step-2-consume-events-rest-with-sse", "priority": -1, "content": "Open a streaming connection to receive events: curl -N https://your-consumer-service.example.com/api/v1beta/events/stream \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -G --data-urlencode &#x27;filter_groups=[{ &quot;event_type&quot;: &quot;myapp.user.created&quot;, &quot;filters&quot;: [] }]&#x27; You\u2019ll receive Server-Sent Events as they occur: event: message data: { &quot;event_type&quot;: &quot;myapp.user.created&quot;, &quot;principal_identity&quot;: &quot;publisher@example.com&quot;, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;published_at&quot;: &quot;2024-10-16T14:30:01Z&quot;, &quot;message&quot;: { &quot;user_id&quot;: &quot;12345&quot;, &quot;username&quot;: &quot;john_doe&quot;, &quot;email&quot;: &quot;john@example.com&quot; } }", "keywords": []}, {"id": 86, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#step-2-publish-an-event-grpc", "display_name": "Step 2: Publish an Event (gRPC)", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "step-2-publish-an-event-grpc", "priority": -1, "content": "import grpc from google.protobuf.timestamp_pb2 import Timestamp from google.protobuf.struct_pb2 import Struct from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2 from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2_grpc # Create channel with credentials credentials = grpc.ssl_channel_credentials() channel = grpc.secure_channel( &#x27;your-aggregation-service.example.com:50051&#x27;, credentials ) stub = event_publisher_pb2_grpc.EventPublishingServiceStub(channel) # Create event message = Struct() message.update({ &#x27;user_id&#x27;: &#x27;12345&#x27;, &#x27;username&#x27;: &#x27;john_doe&#x27;, &#x27;email&#x27;: &#x27;john@example.com&#x27; }) timestamp = Timestamp() timestamp.GetCurrentTime() event = event_publisher_pb2.Event( event_type=&#x27;myapp.user.created&#x27;, message=message, occurred_at=timestamp, resource=event_publisher_pb2.EventResource( resource_id=&#x27;/users/12345&#x27; ) ) # Publish event request = event_publisher_pb2.PublishEventRequest(event=event) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] response = stub.PublishEvent(request, metadata=metadata) print(f&quot;Published successfully: {response.result.success}&quot;)", "keywords": []}, {"id": 87, "doc_id": 88, "filename": "getting-started.html", "domain_name": "page", "name": "getting-started#step-3-consume-events-grpc", "display_name": "Step 3: Consume Events (gRPC)", "type": "section", "display_type": "Page section", "docname": "getting-started", "anchor": "step-3-consume-events-grpc", "priority": -1, "content": "import grpc from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2 from nvidia.omniverse.notifications.consumer.v1beta import event_consumer_pb2_grpc # Create channel with credentials credentials = grpc.ssl_channel_credentials() channel = grpc.secure_channel( &#x27;your-consumer-service.example.com:50052&#x27;, credentials ) stub = event_consumer_pb2_grpc.EventConsumerServiceStub(channel) # Create filter groups filter_group = event_consumer_pb2.FilterGroup( event_type=&#x27;myapp.user.created&#x27; ) # No filters added - receive all events of this type # Create request stream def request_stream(): request = event_consumer_pb2.ConsumeNonDurableEventsRequest() request.filter_groups.append(filter_group) yield request # Consume events metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] responses = stub.ConsumeNonDurableEvents(request_stream(), metadata=metadata) for response in responses: # Process each batch of events for event in response.events: print(f&quot;Received event: {event.event_type}&quot;) print(f&quot;Message: {event.message}&quot;) print(f&quot;Occurred at: {event.occurred_at}&quot;)", "keywords": []}, {"id": 88, "doc_id": 88, "filename": "getting-started.html", "domain_name": "std", "name": "getting-started", "display_name": "Getting Started", "type": "doc", "display_type": "Page", "docname": "getting-started", "anchor": "", "priority": -1, "content": "This guide will help you quickly set up and start using the Notifications Service to publish and consume events.", "keywords": []}, {"id": 89, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#architecture-overview", "display_name": "Architecture Overview", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "architecture-overview", "priority": -1, "content": "The service consists of two independent services:  Event Aggregation Service (Publisher API) - Accepts events from publishers and routes them to RabbitMQ  Event Consumer Service (Consumer API) - Allows consumers to stream events from RabbitMQ with filtering and permissions Your App Your App (Publisher) Notifications Service Infrastructure (Consumer) \u2502 \u2502 \u2502 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 \u2502 \u2502 \u2502 \u2502 \u2502 \u2502 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500&gt;\u2502 \u2502 Event \u2502\u2500\u2500\u2500&gt;\u2502 RabbitMQ \u2502 \u2502\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 Aggregation \u2502 \u2502 (Message \u2502 \u2502 \u2502 \u2502 Service (API) \u2502 \u2502 Broker) \u2502 \u2502 \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 \u2502 \u2502 \u2502 \u2193 \u2502 \u2502 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 \u2502 \u2502 Event \u2502 \u2502 \u2502 \u2502 Consumer \u2502 \u2502 \u2502 \u2502 Service \u2502 \u2502 \u2502 \u2502 (API) \u2502 \u2502 \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518  What this means:   Your App (Publisher) : Any service you build that needs to publish events (e.g., a storage service publishing \u201cfile created\u201d events)  Event Aggregation Service : The Notifications Service API that receives your published events  RabbitMQ : The message broker (managed by the Notifications Service)  Event Consumer Service : The Notifications Service API that streams events to consumers  Your App (Consumer) : Any service you build that needs to consume events (e.g., a thumbnail generator listening for file created events) The Notifications Service = Event Aggregation Service + RabbitMQ + Event Consumer Service (the infrastructure in the box). You just interact with the two APIs.", "keywords": []}, {"id": 90, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#available-apis", "display_name": "Available APIs", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "available-apis", "priority": -1, "content": "Both services provide dual APIs:  gRPC API : High-performance, strongly-typed, ideal for service-to-service communication  REST API : HTTP/JSON-based, easier for testing and web clients, uses Server-Sent Events (SSE) for streaming", "keywords": []}, {"id": 91, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#documentation-structure", "display_name": "Documentation Structure", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "documentation-structure", "priority": -1, "content": "Getting Started Prerequisites Authentication Quick Example: Publish and Consume an Event Quick Example: gRPC Common Patterns Next Steps Troubleshooting Publishing Events Overview Event Structure Publishing a Single Event Batch Publishing Multiple Events Error Handling Best Practices Performance Considerations Next Steps Consuming Events Overview Durable vs Non-Durable Queues Consuming with Non-Durable Queues Consuming with Durable Queues Resource Filtering Error Handling Best Practices Complete Example: Thumbnail Generation Service Next Steps Permissions &amp; Authorization Overview Authentication Publishing Permissions Consuming Permissions Storage Events: Special \u201cDocs\u201d Permissions Fine-Grained Permissions for Arbitrary Event Types Permissions Decision Flow Summary Table Configuration Examples Best Practices Troubleshooting Next Steps API Reference API Types Event Aggregation Service (Publisher API) Publisher gRPC API Publisher REST API Event Consumer Service (Consumer API) Consumer gRPC API Consumer REST API Error Handling Protocol Buffer Files OpenAPI Specifications Rate Limits and Quotas Versioning Service Health Metrics and Monitoring Next Steps", "keywords": []}, {"id": 92, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#durable-vs-non-durable-queues", "display_name": "Durable vs Non-Durable Queues", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "durable-vs-non-durable-queues", "priority": -1, "content": "The Consumer API supports two consumption modes:  Non-Durable Queues : Receive only events that occur while actively connected Lightweight, no setup required Best for real-time updates where missing messages is acceptable Automatically cleaned up when disconnected  Durable Queues : Persist events even when disconnected Must be explicitly created before use Receive all events from the time the queue was created Best for critical event processing where no events should be missed Require explicit cleanup when no longer needed See the Consuming Events guide for details on when to use each type.", "keywords": []}, {"id": 93, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#event-types-and-message-contracts", "display_name": "Event Types and Message Contracts", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "event-types-and-message-contracts", "priority": -1, "content": "Important : The Notifications Service is event-type agnostic . This means: The service does not know or validate the structure of your event types or message bodies Event types and message schemas are contracts between publishers and consumers Publishers and consumers must agree on: What event type strings to use What structure the message JSON should have What the resource_id paths represent For example, if you\u2019re building a thumbnail service: Define your own event types like \u201cthumbnail.created\u201d or \u201cthumbnail.updated\u201d Document the message structure (e.g., {&quot;thumbnail_url&quot;: &quot;...&quot;, &quot;size&quot;: &quot;...&quot;} ) Ensure both publishers and consumers use the same schema", "keywords": []}, {"id": 94, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#events", "display_name": "Events", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "events", "priority": -1, "content": "Events represent something that happened in your system. Each event has:  event_type : A string identifying the type of event (e.g., \u201cstorage.file.created\u201d)  message : JSON payload containing event-specific data  occurred_at : Timestamp when the event occurred  resource : Optional path-like identifier for filtering (e.g., \u201c/folder/subfolder/file.txt\u201d)", "keywords": []}, {"id": 95, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#quick-links", "display_name": "Quick Links", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "quick-links", "priority": -1, "content": "Getting Started Guide - Set up and run your first example Publishing Events - Learn how to publish events (REST and gRPC) Consuming Events - Learn how to consume events (REST and gRPC) Permissions &amp; Authorization - Understanding access control API Reference - Detailed API documentation", "keywords": []}, {"id": 96, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#resource-filtering", "display_name": "Resource Filtering", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "resource-filtering", "priority": -1, "content": "Events can include a hierarchical resource_id (like a file path) that consumers can filter on:  Exact match : Only events for a specific resource  Prefix match (lazy) : Events for resources at a specific level  Prefix match (greedy) : Events for resources and all sub-levels Example: Resource: &quot;/projects/projectA/file.txt&quot; Filter &quot;/projects/projectA/&quot; (greedy) \u2192 Matches \u2713 Filter &quot;/projects/&quot; (greedy) \u2192 Matches \u2713 Filter &quot;/projects/&quot; (lazy) \u2192 No match \u2717 (file is nested too deep)", "keywords": []}, {"id": 97, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#support-and-contributing", "display_name": "Support and Contributing", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "support-and-contributing", "priority": -1, "content": "For questions, issues, or contributions, please contact the Omniverse Notifications Service team.", "keywords": []}, {"id": 98, "doc_id": 99, "filename": "index.html", "domain_name": "page", "name": "index#what-is-the-notifications-service", "display_name": "What is the Notifications Service?", "type": "section", "display_type": "Page section", "docname": "index", "anchor": "what-is-the-notifications-service", "priority": -1, "content": "The Notifications Service provides a way for applications to:  Publish events when significant actions occur (e.g., file created, user updated, workflow completed)  Consume events in real-time to react to changes happening across the system  Filter events to receive only the specific events your application cares about  Control access through fine-grained permissions on both publishing and consuming", "keywords": []}, {"id": 99, "doc_id": 99, "filename": "index.html", "domain_name": "std", "name": "index", "display_name": "Omniverse Notifications APIs Developer Guide", "type": "doc", "display_type": "Page", "docname": "index", "anchor": "", "priority": -1, "content": "The Notifications Service is a distributed event messaging system that enables real-time event publishing and consumption across NVIDIA Omniverse services. It consists of two main components working together to provide a scalable, permission-aware event streaming infrastructure.", "keywords": []}, {"id": 100, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#authentication", "display_name": "Authentication", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "authentication", "priority": -1, "content": "All requests to both the Event Aggregation Service and Event Consumer Service require authentication via bearer tokens.", "keywords": []}, {"id": 101, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#complete-configuration-example", "display_name": "Complete Configuration Example", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "complete-configuration-example", "priority": -1, "content": "YAML file ( /etc/event-consumer/permissions.yml ): # Storage API endpoints for &quot;docs&quot; permissions storage_permissions_endpoints: - https://storage-api.example.com # Fine-grained event permissions event_permissions: # Project events - event_type: project.created action: read-project - event_type: project.updated action: read-project - event_type: project.deleted action: read-project # Thumbnail events - event_type: thumbnail.generated action: read-thumbnail # Notification events - event_type: notification.created action: read-notification # Workflow events - event_type: workflow.completed action: read-workflow  Corresponding Policies : // User can see their own project events permit( principal == Principal::&quot;user@example.com&quot;, action in [ Action::&quot;event-consumer-service:read-project&quot; ], resource == EventResourceId ) when { // Check if resource (project) is owned by user resource.owner == principal.id }; // User can see thumbnails for files they can access permit( principal == Principal::&quot;user@example.com&quot;, action == Action::&quot;event-consumer-service:read-thumbnail&quot;, resource == EventResourceId ) when { // Check via storage permissions resource.accessible_by(principal) }; // All users can see notification events for their own notifications permit( principal, action == Action::&quot;event-consumer-service:read-notification&quot;, resource == EventResourceId ) when { resource.recipient == principal.id };", "keywords": []}, {"id": 102, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#configuration", "display_name": "Configuration", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "configuration", "priority": -1, "content": "The Event Aggregation Service is configured via environment variables: Variable Description OMNI_EVENTS_PERMISSIONS_ENDPOINT URL of the permissions service. If not set, permissions checks are disabled . OMNI_EVENTS_PERMISSIONS_TTL_SECONDS Cache TTL for permissions checks (default: 600)  Example : OMNI_EVENTS_PERMISSIONS_ENDPOINT=https://permissions.example.com OMNI_EVENTS_PERMISSIONS_TTL_SECONDS=300", "keywords": []}, {"id": 103, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#configuration-for-storage-events", "display_name": "Configuration for Storage Events", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "configuration-for-storage-events", "priority": -1, "content": "The Event Consumer Service needs to know which Storage API endpoints to query:  Environment Variable : OMNI_EVENTS_PERMISSIONS_YAML_FILE_PATH  YAML Configuration File : storage_permissions_endpoints: - https://storage-api-1.example.com - https://storage-api-2.example.com  Example : OMNI_EVENTS_PERMISSIONS_YAML_FILE_PATH=/etc/event-consumer/permissions.yml  In the YAML file ( /etc/event-consumer/permissions.yml ): storage_permissions_endpoints: - https://azure-blob-storage-api.example.com - https://s3-storage-api.example.com Currently, the first endpoint in the list is used. In the future, routing rules will determine which endpoint to use based on the event\u2019s resource_id .", "keywords": []}, {"id": 104, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#consume-from-durable-queue", "display_name": "Consume from Durable Queue", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "consume-from-durable-queue", "priority": -1, "content": "Action : consume-durable-queues  Resource : None (service-level permission)  Policy Example : permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:consume-durable-queues&quot; );", "keywords": []}, {"id": 105, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#consuming-permissions", "display_name": "Consuming Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "consuming-permissions", "priority": -1, "content": "Consuming permissions are more complex because they involve: General permissions for queue management Special handling for storage events Optional fine-grained per-event-type permissions", "keywords": []}, {"id": 106, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#create-durable-queue", "display_name": "Create Durable Queue", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "create-durable-queue", "priority": -1, "content": "Action : create-durable-queues  Resource : None (service-level permission)  Policy Example : permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:create-durable-queues&quot; );", "keywords": []}, {"id": 107, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#delete-durable-queue", "display_name": "Delete Durable Queue", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "delete-durable-queue", "priority": -1, "content": "Action : delete-durable-queues  Resource : None (service-level permission)  Policy Example : permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:delete-durable-queues&quot; );", "keywords": []}, {"id": 108, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#document-your-permission-requirements", "display_name": "2. Document Your Permission Requirements", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "document-your-permission-requirements", "priority": -1, "content": "When defining new event types, document what permissions are needed: &quot;&quot;&quot; Event Type: project.updated Publishing Permission: - Action: publish-event - Resource: EventType::&quot;project.updated&quot; Consuming Permission (fine-grained): - Action: read-project - Resource: EventResourceId (project&#x27;s resource_id) Example policy: permit( principal, action == Action::&quot;event-consumer-service:read-project&quot;, resource == EventResourceId ) when { resource.members.contains(principal.id) }; &quot;&quot;&quot;", "keywords": []}, {"id": 109, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#durable-queue-event-permissions", "display_name": "Durable Queue Event Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "durable-queue-event-permissions", "priority": -1, "content": "When consuming from a durable queue, additional permissions checks are performed on individual events based on their event type.  For storage events , the service checks: storage.file.created \u2192 Action: consume-all-storage-create-events storage.file.deleted \u2192 Action: consume-all-storage-delete-events  Policy Example : // Allow thumbnail service to consume all file creation events permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:consume-all-storage-create-events&quot; );  For non-storage events with configured permissions (see the Fine-Grained Permissions for Arbitrary Event Types section below), the action and resource from the configuration are used.", "keywords": []}, {"id": 110, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#durable-queue-permissions", "display_name": "Durable Queue Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "durable-queue-permissions", "priority": -1, "content": "To work with durable queues, principals need specific permissions:", "keywords": []}, {"id": 111, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#durable-queues", "display_name": "Durable Queues", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "durable-queues", "priority": -1, "content": "\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Event Received \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Is it a storage event? \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 Yes \u2502 No \u25bc \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Check: \u2502 \u2502 Is event_type configured \u2502 \u2502 - storage.created \u2502 \u2502 in permissions.yml? \u2502 \u2502 \u2192 consume-all- \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2518 \u2502 storage-create \u2502 \u2502 Yes \u2502 No \u2502 -events \u2502 \u25bc \u25bc \u2502 - storage.deleted \u2502 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 \u2192 consume-all- \u2502 \u2502 Check perms \u2502 \u2502 Allow \u2502 \u2502 storage-delete \u2502 \u2502 API with \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 -events \u2502 \u2502 action + \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 resource_id \u2502 \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 \u25bc \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Allow or Deny? \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 Allow \u2502 Deny \u25bc \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Deliver Event \u2502 \u2502 Filter Out Event \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518", "keywords": []}, {"id": 112, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#event-type-permissions", "display_name": "Event Type Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "event-type-permissions", "priority": -1, "content": "To publish an event, the authenticated principal must have permission for that specific event type. The Event Aggregation Service checks permissions using:  Action : publish-event  Resource Type : EventType  Resource ID : The event_type string (e.g., \u201cstorage.file.created\u201d)", "keywords": []}, {"id": 113, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#example-1-thumbnail-service-durable-queue", "display_name": "Example 1: Thumbnail Service (Durable Queue)", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "example-1-thumbnail-service-durable-queue", "priority": -1, "content": "The thumbnail service needs to process all file creation events.  Permissions Policies : permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:create-durable-queues&quot; ); permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:consume-durable-queues&quot; ); permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:consume-all-storage-create-events&quot; );  No YAML configuration needed - the service uses simple action-based permissions.", "keywords": []}, {"id": 114, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#example-2-user-dashboard-non-durable-queue", "display_name": "Example 2: User Dashboard (Non-Durable Queue)", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "example-2-user-dashboard-non-durable-queue", "priority": -1, "content": "A web dashboard shows users file events for files they have access to.  Permissions Policies : // No special policies needed - users use their existing storage permissions // The Event Consumer Service will query the Storage API to check access  YAML Configuration ( /etc/event-consumer/permissions.yml ): storage_permissions_endpoints: - https://storage-api.example.com", "keywords": []}, {"id": 115, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#example-3-project-notification-service-non-durable-fine-grained", "display_name": "Example 3: Project Notification Service (Non-Durable + Fine-Grained)", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "example-3-project-notification-service-non-durable-fine-grained", "priority": -1, "content": "A service that shows users events for projects they have access to.  Permissions Policies : permit( principal, action in [ Action::&quot;event-consumer-service:read-project&quot; ], resource == EventResourceId ) when { // User has access if they&#x27;re a member of the project resource.members.contains(principal.id) };  YAML Configuration : event_permissions: - event_type: project.created action: read-project - event_type: project.updated action: read-project - event_type: project.deleted action: read-project - event_type: project.member.added action: read-project", "keywords": []}, {"id": 116, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#example-policy", "display_name": "Example Policy", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "example-policy", "priority": -1, "content": "In your permissions service (e.g., Cedar policy): // Allow user to publish storage events permit( principal == Principal::&quot;user@example.com&quot;, action == Action::&quot;event-aggregation-service:publish-event&quot;, resource == EventType::&quot;storage.file.created&quot; ); // Allow a service to publish workflow events permit( principal == Principal::&quot;workflow-service&quot;, action == Action::&quot;event-aggregation-service:publish-event&quot;, resource == EventType::&quot;workflow.completed&quot; );", "keywords": []}, {"id": 117, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#fine-grained-permissions-for-arbitrary-event-types", "display_name": "Fine-Grained Permissions for Arbitrary Event Types", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "fine-grained-permissions-for-arbitrary-event-types", "priority": -1, "content": "For non-storage event types, you can configure fine-grained permissions that check not just the event type, but also the resource_id from the event.", "keywords": []}, {"id": 118, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#for-storage-dir-created-events", "display_name": "For storage.dir_created Events", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "for-storage-dir-created-events", "priority": -1, "content": "When a directory is created: The service checks if the user has access to the parent directory  It queries the Storage API to see if they have any files in the new directory  If they have files in the new directory, they receive the event The directory is added to the cache", "keywords": []}, {"id": 119, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#for-storage-dir-deleted-events", "display_name": "For storage.dir_deleted Events", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "for-storage-dir-deleted-events", "priority": -1, "content": "When a directory is deleted: The service checks if the user had access to the directory (from the cache) It checks if they still have files in that \u201cdeleted\u201d directory (in case it\u2019s a synthetic delete event) If the directory was truly deleted for them, they receive the event The directory is removed from the cache", "keywords": []}, {"id": 120, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#for-storage-file-created-events", "display_name": "For storage.file.created Events", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "for-storage-file-created-events", "priority": -1, "content": "When a file is created: The consumer service checks if the user has access to the parent directory  If they have any files in that directory (i.e., they can \u201csee\u201d the directory), they receive the event The file is added to a cache so that if it\u2019s deleted later, the service knows they should receive the delete event", "keywords": []}, {"id": 121, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#for-storage-file-deleted-events", "display_name": "For storage.file.deleted Events", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "for-storage-file-deleted-events", "priority": -1, "content": "When a file is deleted: The service checks if the user had access to that file (from the cache or by checking the parent directory) If they had access, they receive the delete event The file is removed from the cache", "keywords": []}, {"id": 122, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#how-it-works", "display_name": "How It Works", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "how-it-works", "priority": -1, "content": "For each event of a configured type: The Event Consumer Service makes a permissions API call It uses the configured action It uses the event\u2019s resource_id as the resource ID The resource type is always EventResourceId If the principal has permission, the event is delivered; otherwise, it\u2019s filtered out", "keywords": []}, {"id": 123, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#how-storage-permissions-work", "display_name": "How Storage Permissions Work", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "how-storage-permissions-work", "priority": -1, "content": "For non-durable queues , the Event Consumer Service queries the Storage API to check if the user has access to the files/directories in the events. This is sometimes called \u201cdocs\u201d permissions because it\u2019s based on the actual documents/files the user can access in storage.", "keywords": []}, {"id": 124, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#id1", "display_name": "Configuration", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "id1", "priority": -1, "content": "Fine-grained permissions are configured via a YAML file specified by the OMNI_EVENTS_PERMISSIONS_YAML_FILE_PATH environment variable.  Environment Variable : OMNI_EVENTS_PERMISSIONS_YAML_FILE_PATH=/etc/event-consumer/permissions.yml  YAML Configuration File : event_permissions: - event_type: project.updated action: read-project - event_type: thumbnail.generated action: read-thumbnail - event_type: notification.created action: read-notification", "keywords": []}, {"id": 125, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#including-auth-token", "display_name": "Including Auth Token", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "including-auth-token", "priority": -1, "content": "REST API : Authorization: Bearer YOUR_JWT_TOKEN  gRPC : metadata = [(&#x27;authorization&#x27;, &#x27;Bearer YOUR_JWT_TOKEN&#x27;)] stub.PublishEvent(request, metadata=metadata)", "keywords": []}, {"id": 126, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#monitor-permission-denials", "display_name": "4. Monitor Permission Denials", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "monitor-permission-denials", "priority": -1, "content": "Log and monitor permission denials to detect: Misconfigured policies Users attempting unauthorized access Services missing required permissions", "keywords": []}, {"id": 127, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#next-steps", "display_name": "Next Steps", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "next-steps", "priority": -1, "content": "Review Publishing Events to understand how to publish with proper authorization Review Consuming Events to understand queue types and consumption patterns Check the API Reference for complete API documentation", "keywords": []}, {"id": 128, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#non-durable-queue-permissions", "display_name": "Non-Durable Queue Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "non-durable-queue-permissions", "priority": -1, "content": "Non-durable queues don\u2019t require special queue management permissions, but every event is checked for permissions before being delivered. This is where the sophisticated permission models come into play:  Storage events : Use storage-API-based \u201cdocs\u201d permissions  Configured event types : Use permissions API with configured actions  Unconfigured event types : No permissions check (allowed by default)", "keywords": []}, {"id": 129, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#non-durable-queues", "display_name": "Non-Durable Queues", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "non-durable-queues", "priority": -1, "content": "\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Event Received \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Is it a storage event? \u2502 \u2502 (storage.created, storage.deleted, etc) \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 Yes \u2502 No \u25bc \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Check Storage API \u2502 \u2502 Is event_type configured \u2502 \u2502 &quot;docs&quot; permissions \u2502 \u2502 in permissions.yml? \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 Yes \u2502 No \u2502 \u25bc \u25bc \u2502 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 \u2502 Check \u2502 \u2502 Allow \u2502 \u2502 \u2502 permissions \u2502 \u2502 (no check) \u2502 \u2502 \u2502 API with \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 configured \u2502 \u2502 \u2502 action + \u2502 \u2502 \u2502 resource_id \u2502 \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 \u2502 \u25bc \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Allow or Deny? \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502 Allow \u2502 Deny \u25bc \u25bc \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502 Deliver Event \u2502 \u2502 Filter Out Event \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518", "keywords": []}, {"id": 130, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#not-receiving-events-with-fine-grained-permissions", "display_name": "Not receiving events with fine-grained permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "not-receiving-events-with-fine-grained-permissions", "priority": -1, "content": "Check : Is the event_type configured in the event_permissions section of the YAML file? Does your policy grant the configured action for the resource_id in the events? Is the resource_id in the events formatted as expected?", "keywords": []}, {"id": 131, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#not-receiving-storage-events-non-durable", "display_name": "Not receiving storage events (non-durable)", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "not-receiving-storage-events-non-durable", "priority": -1, "content": "Check : Is storage_permissions_endpoints configured correctly in the YAML file? Does the Storage API show that the user has access to files in the relevant directories? Are the event types correct? (Check the actual event type strings used by your storage service)", "keywords": []}, {"id": 132, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#overview", "display_name": "Overview", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "overview", "priority": -1, "content": "The Notifications Service integrates with a permissions API to control:  Who can publish events of specific types  Who can create, delete, and consume from durable queues   Who can consume specific events from non-durable queues  Fine-grained access control based on event content", "keywords": []}, {"id": 133, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#permission-denied-when-creating-durable-queue", "display_name": "\u201cPermission denied\u201d when creating durable queue", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "permission-denied-when-creating-durable-queue", "priority": -1, "content": "Check : Does your principal have create-durable-queues permission? Is your auth token valid?", "keywords": []}, {"id": 134, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#permission-denied-when-publishing", "display_name": "\u201cPermission denied\u201d when publishing", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "permission-denied-when-publishing", "priority": -1, "content": "Check : Is OMNI_EVENTS_PERMISSIONS_ENDPOINT configured? Does your principal have publish-event permission for the EventType? Is your auth token valid and not expired?", "keywords": []}, {"id": 135, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#permissions-api-call", "display_name": "Permissions API Call", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "permissions-api-call", "priority": -1, "content": "When consuming an event like: { &quot;event_type&quot;: &quot;project.updated&quot;, &quot;resource_id&quot;: &quot;/projects/project-123&quot;, &quot;message&quot;: {} } The service makes this permissions check:  Principal : The authenticated user  Action : read-project (from config)  Resource Type : EventResourceId  Resource ID : /projects/project-123 (from event)", "keywords": []}, {"id": 136, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#permissions-decision-flow", "display_name": "Permissions Decision Flow", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "permissions-decision-flow", "priority": -1, "content": "Here\u2019s how permissions are checked when consuming events:", "keywords": []}, {"id": 137, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#policy-examples", "display_name": "Policy Examples", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "policy-examples", "priority": -1, "content": "Scoped Policy (using resource_id): // Allow user to see events for project-123 permit( principal == Principal::&quot;user@example.com&quot;, action == Action::&quot;event-consumer-service:read-project&quot;, resource == EventResourceId::&quot;/projects/project-123&quot; );  Global Policy (ignoring resource_id): // Allow admin to see all project events permit( principal == Principal::&quot;admin@example.com&quot;, action == Action::&quot;event-consumer-service:read-project&quot; );  Hierarchical Policy : // Allow user to see events for any project they own permit( principal == Principal::&quot;user@example.com&quot;, action == Action::&quot;event-consumer-service:read-project&quot;, resource == EventResourceId ) when { resource in Principal::&quot;user@example.com&quot; };", "keywords": []}, {"id": 138, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#rest-example", "display_name": "REST Example", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "rest-example", "priority": -1, "content": "curl -X POST https://your-aggregation-service.example.com/api/v1beta/events \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;event&quot;: { &quot;event_type&quot;: &quot;myapp.user.created&quot;, ... } }&#x27; If the principal doesn\u2019t have publish-event permission for EventType::&quot;myapp.user.created&quot; , you\u2019ll receive: HTTP 403 Forbidden { &quot;detail&quot;: &quot;Not allowed to publish events of type myapp.user.created&quot; }", "keywords": []}, {"id": 139, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#storage-event-types", "display_name": "Storage Event Types", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "storage-event-types", "priority": -1, "content": "The following event types are treated as storage events: omni.storage.created - File created omni.storage.deleted - File deleted omni.storage.dir_created - Directory created omni.storage.dir_deleted - Directory deleted (Note: The actual event type strings may vary based on your storage service configuration)", "keywords": []}, {"id": 140, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#storage-events-special-docs-permissions", "display_name": "Storage Events: Special \u201cDocs\u201d Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "storage-events-special-docs-permissions", "priority": -1, "content": "Storage events have special handling because they relate to files and directories that have their own access control in the Storage API.", "keywords": []}, {"id": 141, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#storage-permissions-with-durable-queues", "display_name": "Storage Permissions with Durable Queues", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "storage-permissions-with-durable-queues", "priority": -1, "content": "Important difference : When using durable queues , storage events don\u2019t use the Storage API \u201cdocs\u201d permissions. Instead, they use simple action-based permissions: storage.file.created \u2192 consume-all-storage-create-events storage.file.deleted \u2192 consume-all-storage-delete-events  Why? Durable queues are typically used by services (not end users) that need to process all storage events, not just those for files they own.  Policy Example : // Thumbnail service can consume all file creation events permit( principal == Principal::&quot;thumbnail-service&quot;, action == Action::&quot;event-consumer-service:consume-all-storage-create-events&quot; ); // Audit service can consume all file deletion events permit( principal == Principal::&quot;audit-service&quot;, action == Action::&quot;event-consumer-service:consume-all-storage-delete-events&quot; );", "keywords": []}, {"id": 142, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#summary-table", "display_name": "Summary Table", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "summary-table", "priority": -1, "content": "Scenario Queue Type Event Type Permission Check Create queue Durable N/A create-durable-queues Delete queue Durable N/A delete-durable-queues Consume from queue Durable N/A consume-durable-queues Storage create event Durable storage.* consume-all-storage-create-events Storage delete event Durable storage.* consume-all-storage-delete-events Storage event Non-durable storage.* Storage API \u201cdocs\u201d permissions Configured event Either Any Configured action + EventResourceId Unconfigured event Either Any No check (allowed) Publishing N/A Any publish-event with EventType", "keywords": []}, {"id": 143, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#test-permissions-thoroughly", "display_name": "3. Test Permissions Thoroughly", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "test-permissions-thoroughly", "priority": -1, "content": "Test both positive and negative cases: Can authorized users publish/consume? Are unauthorized users properly denied? Do permissions work correctly after token refresh? Are fine-grained permissions enforced correctly?", "keywords": []}, {"id": 144, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#token-expiration", "display_name": "Token Expiration", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "token-expiration", "priority": -1, "content": "Important : Tokens can expire while you\u2019re streaming events . When this happens: The stream will terminate with a 401 (UNAUTHENTICATED) error Your client must refresh the token Reconnect with the fresh token  Non-durable queues : Use the reconnect_token to avoid missing events  Durable queues : Simply reconnect with the same queue_id See the Consuming Events guide for code examples.", "keywords": []}, {"id": 145, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#token-expiring-during-stream", "display_name": "Token expiring during stream", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "token-expiring-during-stream", "priority": -1, "content": "Solution : Implement automatic token refresh and reconnection. See Consuming Events - Error Handling .", "keywords": []}, {"id": 146, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#use-hierarchical-policies-where-appropriate", "display_name": "5. Use Hierarchical Policies Where Appropriate", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "use-hierarchical-policies-where-appropriate", "priority": -1, "content": "For resource hierarchies, use hierarchical policies: // Allow user to see events for anything in their workspace permit( principal == Principal::&quot;user@example.com&quot;, action == Action::&quot;event-consumer-service:read-file&quot;, resource == EventResourceId ) when { resource.path.startsWith(&quot;/workspaces/&quot; + principal.workspace_id + &quot;/&quot;) };", "keywords": []}, {"id": 147, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#use-service-accounts-for-durable-queues", "display_name": "1. Use Service Accounts for Durable Queues", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "use-service-accounts-for-durable-queues", "priority": -1, "content": "Create dedicated service principals for services using durable queues: permit( principal == Principal::&quot;service:thumbnail-generator&quot;, action == Action::&quot;event-consumer-service:create-durable-queues&quot; );", "keywords": []}, {"id": 148, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#when-to-use-fine-grained-permissions", "display_name": "When to Use Fine-Grained Permissions", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "when-to-use-fine-grained-permissions", "priority": -1, "content": "Use fine-grained permissions when: Different users should see different events of the same type Events relate to resources with their own access control (like files, projects, workspaces) You need to enforce permissions based on the event\u2019s resource_id  Examples : A user should only see project.updated events for projects they have access to A user should only see thumbnail.generated events for their own files A user should only see notification.created events for notifications sent to them", "keywords": []}, {"id": 149, "doc_id": 150, "filename": "permissions.html", "domain_name": "page", "name": "permissions#why-docs-permissions", "display_name": "Why \u201cDocs\u201d Permissions?", "type": "section", "display_type": "Page section", "docname": "permissions", "anchor": "why-docs-permissions", "priority": -1, "content": "This approach ensures that: Users only see events for files they have access to A user creating a file in a shared folder only sees that event if they can access the folder Delete events are only sent if the user could see the file/directory in the first place Permissions are enforced at the storage layer, not duplicated in the events system", "keywords": []}, {"id": 150, "doc_id": 150, "filename": "permissions.html", "domain_name": "std", "name": "permissions", "display_name": "Permissions & Authorization", "type": "doc", "display_type": "Page", "docname": "permissions", "anchor": "", "priority": -1, "content": "This guide explains how authentication and authorization work in the Notifications Service, including special cases for storage events and configurable per-event-type permissions.", "keywords": []}, {"id": 151, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#batch-publishing-multiple-events", "display_name": "Batch Publishing Multiple Events", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "batch-publishing-multiple-events", "priority": -1, "content": "When you need to publish multiple events, use batch publishing for better performance. Events in a batch are published in parallel.", "keywords": []}, {"id": 152, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#batch-when-possible", "display_name": "4. Batch When Possible", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "batch-when-possible", "priority": -1, "content": "If publishing multiple events at once, use batch publishing: # Good - batch publish events = [create_event(file) for file in uploaded_files] batch_publish(events) # Bad - individual publishes in a loop for file in uploaded_files: publish_event(create_event(file)) # Slower", "keywords": []}, {"id": 153, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#choose-appropriate-event-granularity", "display_name": "1. Choose Appropriate Event Granularity", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "choose-appropriate-event-granularity", "priority": -1, "content": "Too granular : # Publishing separate events for every field change publish_event(&quot;user.email.changed&quot;, {...}) publish_event(&quot;user.name.changed&quot;, {...}) publish_event(&quot;user.phone.changed&quot;, {...})  Better : # Single event for the update with changed fields in message publish_event(&quot;user.updated&quot;, { &quot;user_id&quot;: &quot;123&quot;, &quot;changed_fields&quot;: [&quot;email&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;new_values&quot;: {...} })", "keywords": []}, {"id": 154, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#common-error-codes", "display_name": "Common Error Codes", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "common-error-codes", "priority": -1, "content": "HTTP Status / gRPC Code Meaning Action 401 / UNAUTHENTICATED Authentication failed Check your token is valid and not expired 403 / PERMISSION_DENIED Not authorized to publish this event type Check permissions configuration 400 / INVALID_ARGUMENT Invalid request format Check your event structure matches the schema 503 / RESOURCE_EXHAUSTED Service temporarily overloaded Retry with exponential backoff 500 / INTERNAL Server error Check service health, contact support", "keywords": []}, {"id": 155, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#document-your-events", "display_name": "7. Document Your Events", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "document-your-events", "priority": -1, "content": "Maintain documentation of your event types and message schemas: &quot;&quot;&quot; Event Type: storage.file.created Description: Published when a new file is uploaded to storage Message Schema: { &quot;file_name&quot;: str, # Name of the file &quot;file_size&quot;: int, # Size in bytes &quot;mime_type&quot;: str, # MIME type of the file &quot;uploaded_by&quot;: str, # Email of uploader &quot;checksum&quot;: str, # SHA-256 checksum (optional) &quot;metadata&quot;: dict # Additional metadata (optional) } Resource ID Format: /path/to/file Example: /uploads/2024/10/document.pdf &quot;&quot;&quot;", "keywords": []}, {"id": 156, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#event-structure", "display_name": "Event Structure", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "event-structure", "priority": -1, "content": "Every event consists of the following fields: Field Type Required Description event_type string Yes A unique identifier for the type of event (e.g., \u201cstorage.file.created\u201d) message JSON object Yes The event payload - structure is defined by you occurred_at timestamp Yes When the event occurred (ISO 8601 format) resource object No Optional resource identifier for filtering", "keywords": []}, {"id": 157, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#event-type", "display_name": "Event Type", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "event-type", "priority": -1, "content": "The event_type is a string that identifies what kind of event this is. You define your own event types - the Notifications Service doesn\u2019t validate or enforce any particular naming scheme.  Recommended conventions : Use dot notation: service.entity.action (e.g., \u201cstorage.file.created\u201d) Be consistent across your organization Document your event types Use lowercase Be specific enough to allow filtering but not so specific that you have too many types Examples: storage.file.created storage.file.deleted storage.directory.created project.workflow.completed user.permission.updated thumbnail.generated", "keywords": []}, {"id": 158, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#grpc-api", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "grpc-api", "priority": -1, "content": "RPC : PublishEvent  Python Example : import grpc from google.protobuf.timestamp_pb2 import Timestamp from google.protobuf.struct_pb2 import Struct from datetime import datetime from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2 from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2_grpc # Setup channel and stub channel = grpc.secure_channel( &#x27;your-aggregation-service.example.com:50051&#x27;, grpc.ssl_channel_credentials() ) stub = event_publisher_pb2_grpc.EventPublishingServiceStub(channel) # Create message message = Struct() message.update({ &#x27;file_name&#x27;: &#x27;document.pdf&#x27;, &#x27;file_size&#x27;: 1024576, &#x27;mime_type&#x27;: &#x27;application/pdf&#x27;, &#x27;uploaded_by&#x27;: &#x27;user@example.com&#x27; }) # Create timestamp timestamp = Timestamp() timestamp.FromDatetime(datetime(2024, 10, 16, 14, 30, 0)) # Create event event = event_publisher_pb2.Event( event_type=&#x27;storage.file.created&#x27;, message=message, occurred_at=timestamp, resource=event_publisher_pb2.EventResource( resource_id=&#x27;/uploads/documents/document.pdf&#x27; ) ) # Publish request = event_publisher_pb2.PublishEventRequest(event=event) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] try: response = stub.PublishEvent(request, metadata=metadata) if response.result.success: print(&quot;Event published successfully&quot;) else: print(f&quot;Failed: {response.result.failure_reason}&quot;) except grpc.RpcError as e: print(f&quot;RPC failed: {e.code()}: {e.details()}&quot;)  Go Example : package main import ( &quot;context&quot; &quot;time&quot; &quot;google.golang.org/grpc&quot; &quot;google.golang.org/grpc/credentials&quot; &quot;google.golang.org/protobuf/types/known/structpb&quot; &quot;google.golang.org/protobuf/types/known/timestamppb&quot; pb &quot;nvidia/omniverse/notifications/publisher/v1beta&quot; ) func main() { // Setup connection creds := credentials.NewTLS(&amp;tls.Config{}) conn, err := grpc.Dial( &quot;your-aggregation-service.example.com:50051&quot;, grpc.WithTransportCredentials(creds), ) if err != nil { panic(err) } defer conn.Close() client := pb.NewEventPublishingServiceClient(conn) // Create message message, _ := structpb.NewStruct(map[string]interface{}{ &quot;file_name&quot;: &quot;document.pdf&quot;, &quot;file_size&quot;: 1024576, &quot;mime_type&quot;: &quot;application/pdf&quot;, &quot;uploaded_by&quot;: &quot;user@example.com&quot;, }) // Create event event := &amp;pb.Event{ EventType: &quot;storage.file.created&quot;, Message: message, OccurredAt: timestamppb.New(time.Now()), Resource: &amp;pb.EventResource{ ResourceId: &quot;/uploads/documents/document.pdf&quot;, }, } // Publish ctx := context.Background() // Add auth metadata ctx = metadata.AppendToOutgoingContext(ctx, &quot;authorization&quot;, &quot;Bearer &quot;+YOUR_TOKEN) resp, err := client.PublishEvent(ctx, &amp;pb.PublishEventRequest{ Event: event, }) if err != nil { panic(err) } if resp.Result.Success { println(&quot;Event published successfully&quot;) } else { println(&quot;Failed:&quot;, resp.Result.FailureReason) } }", "keywords": []}, {"id": 159, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#handle-partial-batch-failures", "display_name": "5. Handle Partial Batch Failures", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "handle-partial-batch-failures", "priority": -1, "content": "When batch publishing, some events may succeed while others fail: response = stub.BatchPublishEvents(request, metadata=metadata) failed_events = [ result.event for result in response.results if not result.success ] if failed_events: # Log failures, retry, or handle them appropriately log_failed_events(failed_events) # Maybe retry just the failed events retry_publish(failed_events)", "keywords": []}, {"id": 160, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#id1", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "id1", "priority": -1, "content": "Endpoint : POST /api/v1beta/events/batch  Example : curl -X POST https://your-aggregation-service.example.com/api/v1beta/events/batch \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;events&quot;: [ { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;message&quot;: { &quot;file_name&quot;: &quot;document1.pdf&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/uploads/document1.pdf&quot; } }, { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;message&quot;: { &quot;file_name&quot;: &quot;document2.pdf&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:01Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/uploads/document2.pdf&quot; } }, { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;message&quot;: { &quot;file_name&quot;: &quot;document3.pdf&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:02Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/uploads/document3.pdf&quot; } } ] }&#x27;  Response : { &quot;results&quot;: [ { &quot;event&quot;: { /* event 1 */ }, &quot;success&quot;: true }, { &quot;event&quot;: { /* event 2 */ }, &quot;success&quot;: true }, { &quot;event&quot;: { /* event 3 */ }, &quot;success&quot;: false, &quot;failure_reason&quot;: &quot;Failed to publish to exchange&quot; } ] }  Important : Always check the results array - some events may succeed while others fail.", "keywords": []}, {"id": 161, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#id2", "display_name": "gRPC API", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "id2", "priority": -1, "content": "RPC : BatchPublishEvents  Python Example : import grpc from google.protobuf.timestamp_pb2 import Timestamp from google.protobuf.struct_pb2 import Struct from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2 from nvidia.omniverse.notifications.publisher.v1beta import event_publisher_pb2_grpc # Setup channel and stub channel = grpc.secure_channel( &#x27;your-aggregation-service.example.com:50051&#x27;, grpc.ssl_channel_credentials() ) stub = event_publisher_pb2_grpc.EventPublishingServiceStub(channel) # Create multiple events events = [] for i in range(3): message = Struct() message.update({ &#x27;file_name&#x27;: f&#x27;document{i+1}.pdf&#x27; }) timestamp = Timestamp() timestamp.GetCurrentTime() event = event_publisher_pb2.Event( event_type=&#x27;storage.file.created&#x27;, message=message, occurred_at=timestamp, resource=event_publisher_pb2.EventResource( resource_id=f&#x27;/uploads/document{i+1}.pdf&#x27; ) ) events.append(event) # Batch publish request = event_publisher_pb2.BatchPublishEventsRequest() for event in events: request.events.append(event) metadata = [(&#x27;authorization&#x27;, f&#x27;Bearer {YOUR_TOKEN}&#x27;)] try: response = stub.BatchPublishEvents(request, metadata=metadata) # Check each result for idx, result in enumerate(response.results): if result.success: print(f&quot;Event {idx+1} published successfully&quot;) else: print(f&quot;Event {idx+1} failed: {result.failure_reason}&quot;) except grpc.RpcError as e: print(f&quot;RPC failed: {e.code()}: {e.details()}&quot;)", "keywords": []}, {"id": 162, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#include-timestamps-accurately", "display_name": "2. Include Timestamps Accurately", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "include-timestamps-accurately", "priority": -1, "content": "Use the actual time the event occurred, not when you\u2019re publishing it: # Good occurred_at = user_created_timestamp # Bad occurred_at = datetime.utcnow() # Time of publishing, not event occurrence", "keywords": []}, {"id": 163, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#keep-messages-reasonably-sized", "display_name": "6. Keep Messages Reasonably Sized", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "keep-messages-reasonably-sized", "priority": -1, "content": "Don\u2019t embed large payloads in events: # Bad - embedding large binary data publish_event(&quot;image.processed&quot;, { &quot;image_data&quot;: base64_encode(large_image) # Don&#x27;t do this! }) # Good - reference the data publish_event(&quot;image.processed&quot;, { &quot;image_url&quot;: &quot;https://storage.example.com/images/123.jpg&quot;, &quot;thumbnail_url&quot;: &quot;https://storage.example.com/thumbs/123.jpg&quot;, &quot;size_bytes&quot;: 1024576 })", "keywords": []}, {"id": 164, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#message", "display_name": "Message", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "message", "priority": -1, "content": "The message field contains the actual event payload as a JSON object. The structure is entirely up to you - define it based on what information consumers need.  Important : The Notifications Service does not validate or know anything about your message structure. It\u2019s a contract between your publishers and consumers.  Best practices : Document your message schema for each event type Include enough information for consumers to process the event Keep messages reasonably sized (avoid embedding large binary data) Use consistent field naming across event types Include identifiers that allow consumers to fetch more data if needed Example message schemas: // storage.file.created { &quot;file_name&quot;: &quot;document.pdf&quot;, &quot;file_size&quot;: 1024576, &quot;mime_type&quot;: &quot;application/pdf&quot;, &quot;uploaded_by&quot;: &quot;user@example.com&quot;, &quot;checksum&quot;: &quot;sha256:abc123...&quot; } // project.workflow.completed { &quot;workflow_id&quot;: &quot;wf-12345&quot;, &quot;workflow_name&quot;: &quot;Rendering Pipeline&quot;, &quot;status&quot;: &quot;success&quot;, &quot;duration_seconds&quot;: 3600, &quot;output_location&quot;: &quot;/renders/output.mp4&quot; }", "keywords": []}, {"id": 165, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#next-steps", "display_name": "Next Steps", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "next-steps", "priority": -1, "content": "Learn how to Consume Events Understand Permissions &amp; Authorization for publishing Review the API Reference for complete API details", "keywords": []}, {"id": 166, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#occurred-at", "display_name": "Occurred At", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "occurred-at", "priority": -1, "content": "An ISO 8601 timestamp indicating when the event occurred. Always use UTC. Format: YYYY-MM-DDTHH:MM:SSZ Example: 2024-10-16T14:30:00Z", "keywords": []}, {"id": 167, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#overview", "display_name": "Overview", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "overview", "priority": -1, "content": "The Event Aggregation Service accepts events from publishers and routes them to consumers through RabbitMQ. Publishers can send individual events or batch multiple events for better performance.", "keywords": []}, {"id": 168, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#performance-considerations", "display_name": "Performance Considerations", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "performance-considerations", "priority": -1, "content": "Batch publishing : Use for multiple events (faster than individual publishes)  Connection pooling : Reuse gRPC channels/connections instead of creating new ones for each publish  Async publishing : If your language/framework supports it, publish asynchronously  Message size : Keep messages under 100KB for optimal performance", "keywords": []}, {"id": 169, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#resource-optional", "display_name": "Resource (Optional)", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "resource-optional", "priority": -1, "content": "The resource field contains a hierarchical identifier (like a file path) that consumers can use for filtering. { &quot;resource_id&quot;: &quot;/folder/subfolder/file.txt&quot; } Resource IDs should be: Path-like (slash-separated) Hierarchical (broader to more specific) Consistent across your event types Examples: /projects/projectA/file.txt /users/12345 /workspaces/ws-001/render/output.mp4 If you omit the resource field, it\u2019s equivalent to including a resource that has resource_id=&quot;&quot; .", "keywords": []}, {"id": 170, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#rest-api", "display_name": "REST API", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "rest-api", "priority": -1, "content": "Endpoint : POST /api/v1beta/events  Example : curl -X POST https://your-aggregation-service.example.com/api/v1beta/events \\ -H &quot;Authorization: Bearer YOUR_TOKEN&quot; \\ -H &quot;Content-Type: application/json&quot; \\ -d &#x27;{ &quot;event&quot;: { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;message&quot;: { &quot;file_name&quot;: &quot;document.pdf&quot;, &quot;file_size&quot;: 1024576, &quot;mime_type&quot;: &quot;application/pdf&quot;, &quot;uploaded_by&quot;: &quot;user@example.com&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/uploads/documents/document.pdf&quot; } } }&#x27;  Response (Success) : { &quot;result&quot;: { &quot;event&quot;: { &quot;event_type&quot;: &quot;storage.file.created&quot;, &quot;message&quot;: { &quot;file_name&quot;: &quot;document.pdf&quot;, &quot;file_size&quot;: 1024576, &quot;mime_type&quot;: &quot;application/pdf&quot;, &quot;uploaded_by&quot;: &quot;user@example.com&quot; }, &quot;occurred_at&quot;: &quot;2024-10-16T14:30:00Z&quot;, &quot;resource&quot;: { &quot;resource_id&quot;: &quot;/uploads/documents/document.pdf&quot; } }, &quot;success&quot;: true } }  Response (Failure) : { &quot;result&quot;: { &quot;event&quot;: { /* event details */ }, &quot;success&quot;: false, &quot;failure_reason&quot;: &quot;Unable to connect to message broker&quot; } }", "keywords": []}, {"id": 171, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#retry-logic", "display_name": "Retry Logic", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "retry-logic", "priority": -1, "content": "Implement retry logic with exponential backoff for transient failures: import time from typing import Callable def publish_with_retry( publish_func: Callable, max_retries: int = 3, initial_delay: float = 1.0 ) -&gt; bool: &quot;&quot;&quot; Retry publishing with exponential backoff. &quot;&quot;&quot; delay = initial_delay for attempt in range(max_retries): try: response = publish_func() if response.result.success: return True else: print(f&quot;Publish failed: {response.result.failure_reason}&quot;) return False except grpc.RpcError as e: if e.code() == grpc.StatusCode.RESOURCE_EXHAUSTED: if attempt &lt; max_retries - 1: print(f&quot;Service overloaded, retrying in {delay}s...&quot;) time.sleep(delay) delay *= 2 # Exponential backoff else: print(&quot;Max retries exceeded&quot;) return False else: # Don&#x27;t retry for other errors print(f&quot;Non-retriable error: {e.code()}&quot;) return False return False # Usage def publish(): return stub.PublishEvent(request, metadata=metadata) success = publish_with_retry(publish)", "keywords": []}, {"id": 172, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "page", "name": "publishing-events#use-resource-ids-consistently", "display_name": "3. Use Resource IDs Consistently", "type": "section", "display_type": "Page section", "docname": "publishing-events", "anchor": "use-resource-ids-consistently", "priority": -1, "content": "Establish conventions for resource IDs across your organization: # Good - consistent path structure &quot;/users/{user_id}&quot; &quot;/projects/{project_id}/files/{file_id}&quot; &quot;/workspaces/{workspace_id}&quot; # Bad - inconsistent &quot;user-123&quot; &quot;project_456/file789&quot; &quot;/workspace:ws-001&quot;", "keywords": []}, {"id": 173, "doc_id": 173, "filename": "publishing-events.html", "domain_name": "std", "name": "publishing-events", "display_name": "Publishing Events", "type": "doc", "display_type": "Page", "docname": "publishing-events", "anchor": "", "priority": -1, "content": "This guide covers how to publish events to the Notifications Service using both the REST API and gRPC API.", "keywords": []}]};